#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
pub struct HeapContractVerification {
    pub schema: String,
    pub path: String,
    pub methods: Vec<String>,
    pub obligations: Vec<ObligationResult>,
    pub passed: bool,
}

#[derive(Clone, Debug)]
struct ClassShape {
    name: String,
    /// Stable runtime identity. Source-local shapes use their source spelling while they are
    /// proved; exported shapes are sealed to a provider-qualified identity.
    identity: String,
    completed_provider: Option<String>,
    externally_assumed: bool,
    defines_custom_new: bool,
    /// Records a source declaration independently of whether that method belongs to the
    /// callable-summary fragment.  Equality lowering must not mistake an omitted summary for
    /// inherited `object.__eq__` behavior.
    defines_eq_override: bool,
    /// True only when the completed module namespace retains the canonical Nagini `Rd` helper
    /// and no method in this class lexically shadows that binding.
    canonical_rd_binding: bool,
    /// Hashability/equality-sensitive collection operations require inherited `object.__hash__`.
    defines_hash_override: bool,
    /// Conservatively records a class-scope binding that could participate in customized
    /// instance checking. The v45 builtin-isinstance rule requires this absent throughout the
    /// complete source MRO.
    defines_instancecheck_override: bool,
    /// Class-dictionary bindings that can intercept otherwise raw instance-field reads.
    defines_dynamic_attribute_access: bool,
    verified_source_allocator: bool,
    has_explicit_constructor: bool,
    constructor_has_exceptional_outcome: bool,
    constructor_dependencies: BTreeSet<String>,
    /// Direct constructor assignments `self.field = SourceClass(...)` whose allocator and
    /// normal outcome were verified. Values are exact runtime class identities.
    exact_constructed_fields: BTreeMap<String, String>,
    constants: BTreeMap<String, Term>,
    fields: BTreeMap<String, HeapFieldType>,
    /// Fields whose layout/effect contract originates in a ContractOnly external provider.
    externally_assumed_fields: BTreeSet<String>,
    predicates: BTreeMap<String, PredicateSummary>,
    properties: BTreeMap<String, PropertySummary>,
    methods: BTreeMap<String, MethodSummary>,
    abstract_methods: BTreeSet<String>,
    constructor: Option<ConstructorSummary>,
    direct_base: Option<String>,
    direct_base_fields: BTreeSet<String>,
    direct_base_constructor: Option<ConstructorSummary>,
    override_obligations: Vec<Obligation>,
}

