#[derive(Clone, Debug)]
pub struct ImportedHeapContractModule {
    module: String,
    /// Public class exports, keyed by the names accepted by `from module import Name`.
    classes: BTreeMap<String, ClassShape>,
    /// Private transitive layout catalog, keyed by stable provider-qualified identity.
    ///
    /// Consumers use this to interpret exported field/signature types without making a
    /// transitive provider class importable from this module.
    canonical_classes: BTreeMap<String, ClassShape>,
    functions: BTreeMap<String, HeapScalarFunctionSummary>,
    /// Private transitive callable catalog keyed by stable provider-qualified identity.
    canonical_functions: BTreeMap<String, HeapScalarFunctionSummary>,
    reference_functions: BTreeMap<String, ReferenceIdentityFunctionSummary>,
    predicates: BTreeMap<String, ModulePredicateSummary>,
    /// Canonical verifier-supplied functions keyed by the public binding exported from this
    /// module. These are declaration-only intrinsics, never executable Python summaries.
    verifier_intrinsics: BTreeMap<String, VerifierIntrinsicFunctionDescriptor>,
    /// Canonical declaration-only nominal descriptors. They carry provider identity across
    /// imports without becoming executable ClassShape or MethodSummary values.
    verifier_intrinsic_classes: BTreeMap<String, VerifierIntrinsicClassDescriptor>,
    /// Verified parametric class summaries. These retain source-checked effects with nominal
    /// parameter placeholders; consumers must instantiate every placeholder before use.
    generic_classes: BTreeMap<String, ImportedHeapGenericClass>,
    /// Opaque proof that Level/WaitLevel descriptors originated in the ABI-validated canonical
    /// provider. Descriptor maps alone are intentionally insufficient to activate semantics.
    certified_level_intrinsics: Option<CertifiedLevelIntrinsics>,
    /// Closed provider metadata that was proved unobserved and therefore deliberately omitted
    /// from every proof environment. Names are retained only to reject a later source import;
    /// literal contents never cross the provider boundary.
    proof_irrelevant_bindings: BTreeSet<String>,
}

impl ImportedHeapContractModule {
    pub(crate) fn from_verifier_intrinsics(
        provider: VerifierIntrinsicProvider,
        certified_level_intrinsics: CertifiedLevelIntrinsics,
    ) -> Self {
        Self {
            module: provider.module,
            classes: BTreeMap::new(),
            canonical_classes: BTreeMap::new(),
            functions: BTreeMap::new(),
            canonical_functions: BTreeMap::new(),
            reference_functions: BTreeMap::new(),
            predicates: BTreeMap::new(),
            verifier_intrinsics: provider.functions,
            verifier_intrinsic_classes: provider.classes,
            generic_classes: BTreeMap::new(),
            certified_level_intrinsics: Some(certified_level_intrinsics),
            proof_irrelevant_bindings: BTreeSet::new(),
        }
    }

    pub fn module(&self) -> &str {
        &self.module
    }

    pub(crate) fn rebound_for_source_import(&self, module: &str) -> Self {
        let mut rebound = self.clone();
        rebound.module = module.to_owned();
        rebound
    }

    pub fn class_names(&self) -> Vec<String> {
        self.classes.keys().cloned().collect()
    }

    pub fn qualified_class_names(&self) -> Vec<String> {
        self.classes
            .keys()
            .map(|name| format!("{}.{name}", self.module))
            .collect()
    }

    pub fn predicate_names(&self) -> Vec<String> {
        self.predicates.keys().cloned().collect()
    }

    pub(crate) fn verifier_intrinsics(
        &self,
    ) -> &BTreeMap<String, VerifierIntrinsicFunctionDescriptor> {
        &self.verifier_intrinsics
    }

    #[cfg(test)]
    pub(crate) fn verifier_intrinsic_classes(
        &self,
    ) -> &BTreeMap<String, VerifierIntrinsicClassDescriptor> {
        &self.verifier_intrinsic_classes
    }

    pub(crate) fn certified_level_intrinsics(&self) -> Option<&CertifiedLevelIntrinsics> {
        self.certified_level_intrinsics.as_ref()
    }

    /// Exact source-verified predicate exports available to downstream contract-position
    /// validation. External heap overlays never populate this catalog; named source re-exports
    /// retain their verified provider summary.
    pub(crate) fn source_predicate_names(&self) -> BTreeSet<String> {
        self.predicates
            .iter()
            .filter(|(_, summary)| summary.source_owned)
            .map(|(name, _)| name.clone())
            .collect()
    }

    pub fn qualified_predicate_names(&self) -> Vec<String> {
        self.predicates
            .keys()
            .map(|name| format!("{}.{name}", self.module))
            .collect()
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct HeapFieldType {
    sort: Sort,
    nominal_class: Option<String>,
    optional: bool,
}

impl HeapFieldType {
    fn scalar(sort: Sort) -> Self {
        Self {
            sort,
            nominal_class: None,
            optional: false,
        }
    }

    fn optional_reference(class: String) -> Self {
        Self {
            sort: Sort::Reference,
            nominal_class: Some(class),
            optional: true,
        }
    }

    fn reference(class: String) -> Self {
        Self {
            sort: Sort::Reference,
            nominal_class: Some(class),
            optional: false,
        }
    }

    fn opaque_reference() -> Self {
        Self {
            sort: Sort::Reference,
            nominal_class: None,
            optional: false,
        }
    }
}

#[derive(Clone, Debug)]
struct MethodSummary {
    /// True only for summaries accepted from a ContractOnly external overlay. Source method
    /// chains must never treat those assumptions as proved source execution.
    externally_assumed: bool,
    receiver_kind: MethodReceiverKind,
    dynamically_constructs_receiver_class: bool,
    declaration_offset: u32,
    positional_only_count: usize,
    parameters: Vec<(String, MethodType)>,
    positional_parameter_count: usize,
    parameter_defaults: Vec<Option<MethodDefault>>,
    var_args: Option<(String, MethodType)>,
    keyword_args: Option<(String, MethodType)>,
    return_type: MethodType,
    preconditions: Vec<ast::Expr>,
    postconditions: Vec<ast::Expr>,
    exception_postconditions: Vec<(String, ast::Expr)>,
    verified_single_return_result: Option<ast::Expr>,
    pure_result: Option<ast::Expr>,
    /// A resolver-certified `@Pure @ContractOnly` declaration denotes a stable, heap-dependent
    /// specification function even though it intentionally has no executable result body.
    opaque_pure: bool,
    /// A conservative, source-verified result equation for ordinary modular execution calls.
    /// Unlike `pure_result`, this is not an advertised contract and must not participate in
    /// override compatibility, specification expression lowering, or conformance diagnostics.
    inferred_result: Option<ast::Expr>,
    /// A total higher-order wrapper whose sole executable action is returning one invocation of
    /// a callable parameter. The call is composed only after a call site supplies exact callable
    /// provenance; opaque values remain uncallable.
    callback_invocation: Option<CallbackInvocationSummary>,
    /// Source spelling of the class that declared this implementation. Inherited summaries retain
    /// their original owner; external/constructor adapters leave this empty and are ineligible for
    /// v46 condition dispatch.
    declaring_class: String,
    call_permission_neutral: bool,
    /// The resolver-certified obligation protocol couples MustRelease ownership with an
    /// instance predicate. Calls transfer the predicate body's concrete permissions rather than
    /// an ordinary folded predicate token.
    obligation_coupled_predicate_transfer: bool,
    neutral_guarded_permissions: Vec<GuardedPermissionContract>,
    modified_fields: BTreeSet<String>,
    /// Direct source-verified writes through nominally typed non-receiver parameters.
    modified_parameter_fields: BTreeMap<String, BTreeSet<String>>,
    called_methods: BTreeSet<String>,
    late_class_dependencies: BTreeSet<LateClassDependency>,
    /// Final immutable module values captured by the method's declaring module.
    ///
    /// This belongs to the summary rather than the containing class: an inherited method must
    /// continue to read its provider's globals even when a subclass is declared elsewhere.
    captured_environment: BTreeMap<String, Term>,
}

