#[derive(Clone, Debug, Eq, PartialEq)]
struct MethodType {
    sort: Sort,
    nominal_class: Option<String>,
    list_element_nominal_class: Option<String>,
    /// Exact ordered element types for a fixed tuple.  Keeping only the immediate nominal class
    /// loses nested Callable and container identity and can make incompatible provider
    /// signatures appear equal.
    tuple_elements: Vec<MethodType>,
    optional: bool,
    accepts_any: bool,
    accepts_any_tuple: bool,
    /// A first-class Python callable shape. Callable values deliberately retain the solver's
    /// reference sort for identity, but this tag is mandatory: an arbitrary heap reference is
    /// never assignment-compatible with `typing.Callable`.
    callable: Option<Box<CallableType>>,
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct CallableType {
    parameters: CallableParameters,
    result: MethodType,
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct CallableValue {
    signature: CallableType,
    provenance: CallableProvenance,
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum CallableProvenance {
    Opaque,
    BoundMethod {
        receiver: Term,
        receiver_class: String,
        method: String,
    },
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum CallableParameters {
    Ellipsis,
    Fixed(Vec<MethodType>),
}

impl CallableType {
    fn opaque() -> Self {
        Self {
            parameters: CallableParameters::Ellipsis,
            result: MethodType::any(),
        }
    }

    /// Python callable assignment is contravariant in parameters and covariant in its result.
    fn accepts(&self, actual: &Self) -> bool {
        let parameters_compatible = match (&self.parameters, &actual.parameters) {
            (CallableParameters::Ellipsis, _) => true,
            (CallableParameters::Fixed(_), CallableParameters::Ellipsis) => false,
            (CallableParameters::Fixed(expected), CallableParameters::Fixed(actual)) => {
                expected.len() == actual.len()
                    && expected
                        .iter()
                        .zip(actual)
                        .all(|(expected_input, actual_input)| {
                            callable_component_compatible(actual_input, expected_input)
                        })
            }
        };
        parameters_compatible && callable_component_compatible(&self.result, &actual.result)
    }
}

/// Compatibility below a `Callable` boundary has to be self-contained. Ordinary method binding
/// deliberately checks nominal subtyping after the generic binding kernel has matched solver
/// sorts. A nested callable has no later expression/provenance pass, so reusing that looser
/// predicate would silently accept unrelated nominal parameter and result classes. Until the
/// callable shape carries a closed class hierarchy, exact nominal identity is the conservative
/// source-level relation here.
fn callable_component_compatible(expected: &MethodType, actual: &MethodType) -> bool {
    if !method_type_compatible(expected, actual) {
        return false;
    }
    if expected.accepts_any {
        return true;
    }
    if let Some(expected_class) = expected.nominal_class.as_deref()
        && actual.nominal_class.as_deref() != Some(expected_class)
    {
        return false;
    }
    if let Some(expected_class) = expected.list_element_nominal_class.as_deref()
        && actual.list_element_nominal_class.as_deref() != Some(expected_class)
    {
        return false;
    }
    if !expected.tuple_elements.is_empty() && expected.tuple_elements != actual.tuple_elements {
        return false;
    }
    true
}

impl MethodType {
    fn scalar(sort: Sort) -> Self {
        let tuple_elements = match &sort {
            Sort::Tuple(elements) => elements.iter().cloned().map(MethodType::scalar).collect(),
            _ => Vec::new(),
        };
        Self {
            sort,
            nominal_class: None,
            list_element_nominal_class: None,
            tuple_elements,
            optional: false,
            accepts_any: false,
            accepts_any_tuple: false,
            callable: None,
        }
    }

    fn any() -> Self {
        Self {
            // The concrete sort remains available on every actual value; `accepts_any` is the
            // only compatibility escape and never changes the term's own sort.
            sort: Sort::Reference,
            nominal_class: None,
            list_element_nominal_class: None,
            tuple_elements: Vec::new(),
            optional: false,
            accepts_any: true,
            accepts_any_tuple: false,
            callable: None,
        }
    }

    fn callable(callable: CallableType) -> Self {
        Self {
            sort: Sort::Reference,
            nominal_class: None,
            list_element_nominal_class: None,
            tuple_elements: Vec::new(),
            optional: false,
            accepts_any: false,
            accepts_any_tuple: false,
            callable: Some(Box::new(callable)),
        }
    }

    fn any_tuple() -> Self {
        Self {
            // The element sorts and arity are supplied by each actual tuple value. This flag,
            // unlike `accepts_any`, accepts no non-tuple value.
            sort: Sort::Tuple(Vec::new()),
            nominal_class: None,
            list_element_nominal_class: None,
            tuple_elements: Vec::new(),
            optional: false,
            accepts_any: false,
            accepts_any_tuple: true,
            callable: None,
        }
    }
}

#[derive(Clone, Debug)]
struct ConstructorSummary {
    declaration_offset: u32,
    receiver: String,
    positional_only_count: usize,
    parameters: Vec<(String, MethodType)>,
    positional_parameter_count: usize,
    parameter_defaults: Vec<Option<Term>>,
    var_args: Option<(String, MethodType)>,
    keyword_args: Option<(String, MethodType)>,
    /// Fields initialized by the compiler-generated dataclass constructor. The parameter name is
    /// the field name; applying the constructor grants full ownership and fixes the initial value.
    dataclass_fields: BTreeSet<String>,
    dataclass_frozen: bool,
    /// Collection-field aliases proven by a straight-line direct `self.field = parameter`
    /// constructor assignment. These are identity facts, not sequence-value equalities.
    proven_collection_aliases: BTreeSet<(String, String)>,
    /// The persistent-sequence subset of the proven aliases. PSeq values are immutable, so a
    /// direct field alias also safely transfers their structural sequence value to callers.
    proven_persistent_sequence_aliases: BTreeSet<(String, String)>,
    preconditions: Vec<ast::Expr>,
    postconditions: Vec<ast::Expr>,
    /// Closed typed exceptional outcomes of the verified constructor body.  These remain
    /// separate from normal postconditions so a caller can compose one path per exit kind.
    exception_postconditions: Vec<(String, ast::Expr)>,
    /// Direct source-verified writes through nominally typed constructor parameters.
    modified_parameter_fields: BTreeMap<String, BTreeSet<String>>,
    late_class_dependencies: BTreeSet<LateClassDependency>,
    /// Final immutable module values captured by the constructor's declaring module.
    captured_environment: BTreeMap<String, Term>,
}

fn class_is_frozen_dataclass(class: &ClassShape) -> bool {
    class
        .constructor
        .as_ref()
        .is_some_and(|constructor| constructor.dataclass_frozen)
}

#[derive(Clone, Debug, Eq, Ord, PartialEq, PartialOrd)]
enum LateClassDependency {
    /// A source-module class whose binding is resolved when the callable executes.
    Local(String),
    /// A provider-owned class whose module initialization completed before export.
    CompletedProvider { module: String, name: String },
}

fn late_class_dependencies_available(
    dependencies: &BTreeSet<LateClassDependency>,
    available_classes: &BTreeMap<String, ClassShape>,
) -> bool {
    dependencies.iter().all(|dependency| match dependency {
        LateClassDependency::Local(name) => available_classes.contains_key(name),
        LateClassDependency::CompletedProvider { .. } => true,
    })
}

fn bind_late_class_dependencies(
    environment: &mut BTreeMap<String, Term>,
    dependencies: &BTreeSet<LateClassDependency>,
    available_classes: &BTreeMap<String, ClassShape>,
) -> Result<(), ContractFailure> {
    if !late_class_dependencies_available(dependencies, available_classes) {
        let missing = dependencies
            .iter()
            .find_map(|dependency| match dependency {
                LateClassDependency::Local(name) if !available_classes.contains_key(name) => {
                    Some(name)
                }
                _ => None,
            })
            .expect("an unavailable dependency has one missing local class");
        return fail(
            "frontend.python.heap.late-class-before-call",
            format!("runtime call occurs before source class {missing:?} is bound"),
        );
    }
    for dependency in dependencies {
        let (binding, identity) = match dependency {
            LateClassDependency::Local(name) => {
                (name.clone(), available_classes[name].identity.clone())
            }
            LateClassDependency::CompletedProvider { module, name } => {
                (name.clone(), format!("{module}.{name}"))
            }
        };
        environment.insert(binding, Term::ClassLiteral { name: identity });
    }
    Ok(())
}

#[derive(Clone, Debug)]
struct Lowered {
    term: Term,
    reads: Vec<HeapRead>,
}

#[derive(Clone, Debug)]
struct TypedConditionalValue {
    lowered: Lowered,
    nominal_class: Option<String>,
    optional: bool,
}

/// One concrete Python value carried by a statement-level control-flow path.
///
/// `and` and `or` return an operand, not a coerced boolean.  Keeping the nominal and allocation
/// provenance beside the solver term lets a selected list or source object retain the same
/// identity and dispatch behavior after short-circuit evaluation.
#[derive(Clone, Debug)]
struct HeapPythonValue {
    term: Term,
    nominal_class: Option<String>,
    optional: bool,
    exact: bool,
    source_constructed: bool,
    list_identity: Option<String>,
}

#[derive(Clone, Debug)]
struct HeapPythonValuePath {
    state: HeapFunctionState,
    value: Option<HeapPythonValue>,
}

#[derive(Default)]
struct FirstHeapBoolOp {
    expression: Option<ast::Expr>,
}

impl Visitor for FirstHeapBoolOp {
    fn visit_expr_bool_op(&mut self, node: ast::ExprBoolOp) {
        if self.expression.is_none() {
            self.expression = Some(ast::Expr::BoolOp(node));
        }
    }
}

struct HeapExpressionRangeRewriter {
    target: rustpython_ast::text_size::TextRange,
    replacement: ast::Expr,
}

impl Fold<rustpython_ast::text_size::TextRange> for HeapExpressionRangeRewriter {
    type TargetU = rustpython_ast::text_size::TextRange;
    type Error = ContractFailure;
    type UserContext = ();

    fn will_map_user(&mut self, _user: &rustpython_ast::text_size::TextRange) {}

    fn map_user(
        &mut self,
        user: rustpython_ast::text_size::TextRange,
        _context: (),
    ) -> Result<rustpython_ast::text_size::TextRange, ContractFailure> {
        Ok(user)
    }

    fn fold_expr(&mut self, node: ast::Expr) -> Result<ast::Expr, ContractFailure> {
        if node.range() == self.target {
            return Ok(self.replacement.clone());
        }
        rustpython_ast::fold::fold_expr(self, node)
    }
}

#[derive(Clone, Debug)]
struct HeapExceptionalExit {
    exception_class: String,
    receiver: Term,
    exact: bool,
    source_constructed: bool,
    byte_offset: u32,
}

#[derive(Clone, Debug)]
enum HeapPendingExit {
    Return(Term),
    Raise(HeapExceptionalExit),
    Break(usize),
    Continue(usize),
}

#[derive(Clone, Debug)]
struct HeapFunctionState {
    environment: BTreeMap<String, Term>,
    /// Proven allocation identity for exact local list values. The solver term represents list
    /// contents, so equal-but-distinct Python lists need a separate identity ledger to distinguish
    /// a real alias (`other = values`) from a fresh copy (`other = list(values)`).
    list_identities: BTreeMap<String, String>,
    /// Concrete contents of fresh builtin `enumerate` iterator objects, keyed by the stable
    /// reference identity stored in `environment`. Keeping the payload separate preserves
    /// Python object identity: two equal enumerations are still distinct iterator objects.
    enumerations: BTreeMap<String, Vec<Term>>,
    /// Guards under which a local introduced by statement-level control flow is defined.
    ///
    /// The environment retains an arbitrary well-sorted value for such a local so lowering can
    /// continue after recording a definedness VC at each read. A failed guard therefore refutes
    /// the program instead of turning ordinary Python undefined-local behavior into a structural
    /// frontend refusal.
    maybe_undefined_locals: BTreeMap<String, Term>,
    object_classes: BTreeMap<String, String>,
    optional_object_names: BTreeSet<String>,
    exact_object_names: BTreeSet<String>,
    source_constructed_names: BTreeSet<String>,
    heap: u32,
    mask: u32,
    assumptions: Vec<Term>,
    obligations: Vec<Obligation>,
    returned: Option<Term>,
    raised: Option<HeapExceptionalExit>,
    /// Exception currently handled by the innermost active `except` suite.
    ///
    /// A caught exception is no longer a pending function exit, so it cannot remain in `raised`
    /// while the handler executes.  Keeping the active exception separately gives a bare
    /// `raise` its Python meaning without conflating it with a newly raised replacement.
    active_exception: Option<HeapExceptionalExit>,
    /// Innermost structured loop depth targeted by a pending `break` exit.
    ///
    /// Keeping this distinct from return and exceptional exits lets nested statement paths stop
    /// immediately without accidentally turning a break into a function exit. The owning loop
    /// consumes only its own depth marker.
    breaking: Option<usize>,
    /// Innermost structured loop depth targeted by a pending `continue` backedge.
    continuing: Option<usize>,
    path_tag: String,
    verification_halted: bool,
    unsupported: Option<ContractFailure>,
}

impl HeapFunctionState {
    fn obligation_path_suffix(&self) -> String {
        if self.path_tag.is_empty() {
            String::new()
        } else {
            format!(":path:{}", self.path_tag)
        }
    }
}

struct HeapBranchContext<'a> {
    classes: &'a BTreeMap<String, ClassShape>,
    module_predicates: &'a BTreeMap<String, ModulePredicateSummary>,
    reference_identity_functions: Option<&'a BTreeMap<String, ReferenceIdentityFunctionSummary>>,
    scalar_calls: &'a ScalarCallContext<'a>,
    heap_functions: &'a BTreeMap<String, HeapModuleFunctionSummary>,
    effect_free_procedures: &'a BTreeMap<String, HeapEffectFreeProcedureSummary>,
    lexical_names: &'a BTreeSet<String>,
    builtin_isinstance_is_canonical: bool,
    verified_methods: &'a [String],
    pure_function_offset: Option<u32>,
    return_nominal_class: Option<&'a str>,
    return_optional: bool,
    caller: &'a str,
    path: &'a str,
    source: &'a str,
}

