pub fn verify_heap_module(
    source: &str,
    path: &str,
    requested_symbols: &[String],
) -> Result<HeapContractVerification, ContractFailure> {
    verify_heap_module_internal(
        source,
        path,
        requested_symbols,
        &[],
        None,
        false,
        false,
        Some("__main__"),
        InformationFlowVerificationProfile::Ordinary,
    )
}

/// Verify one source module under an explicitly selected information-flow profile.
///
/// Ordinary callers should continue to use [`verify_heap_module`].  This entrypoint exists for
/// callers that bind the verification mode independently of source filenames or source text.
pub fn verify_heap_module_with_information_flow_profile(
    source: &str,
    path: &str,
    requested_symbols: &[String],
    information_flow: InformationFlowVerificationProfile,
) -> Result<HeapContractVerification, ContractFailure> {
    verify_heap_module_internal(
        source,
        path,
        requested_symbols,
        &[],
        None,
        false,
        false,
        Some("__main__"),
        information_flow,
    )
}

/// Reports whether source contains a heap-specific statement-condition shape.
///
/// This is deliberately a syntactic routing predicate, not a proof decision: the heap verifier
/// still validates every detected call or chained comparison, including dispatch, operand types,
/// evaluation effects, and result sort, before accepting it. Keeping the predicate AST-based
/// ensures the production frontend reaches those checks for anchor-free class programs instead of
/// depending on an unrelated `Acc`, `self`, or `isinstance` spelling elsewhere in the file.
pub fn source_has_heap_statement_condition_feature(source: &str, path: &str) -> bool {
    let Ok(suite) = ast::Suite::parse(source, path) else {
        return false;
    };
    suite.iter().any(statement_has_heap_condition_feature)
}

/// Parsed, source-ordered activation predicate for the ordinary heap proof.
///
/// Merely importing the contracts library is not activation. A canonical binding must be live at
/// the declaration that uses it, and callable-local shadowing disables that binding. This is a
/// routing decision only; the heap verifier still checks the complete expression and effects.
pub fn source_activates_ordinary_heap_semantics(
    source: &str,
    path: &str,
) -> Result<bool, ContractFailure> {
    const HELPERS: [&str; 5] = ["Acc", "Rd", "Fold", "Unfold", "Unfolding"];

    struct ActivationUse<'a> {
        active: &'a BTreeSet<String>,
        found: bool,
    }
    impl Visitor for ActivationUse<'_> {
        fn visit_expr_call(&mut self, node: ast::ExprCall) {
            if matches!(node.func.as_ref(), ast::Expr::Name(name)
                if self.active.contains(name.id.as_str()))
            {
                self.found = true;
            }
            self.generic_visit_expr_call(node);
        }
    }

    fn function_uses_heap(
        function: &ast::StmtFunctionDef,
        canonical: &BTreeSet<String>,
    ) -> Result<bool, ContractFailure> {
        let lexical = callable_lexical_names(function)?;
        let active = canonical
            .iter()
            .filter(|name| !lexical.contains(name.as_str()))
            .cloned()
            .collect::<BTreeSet<_>>();
        let mut visitor = ActivationUse {
            active: &active,
            found: false,
        };
        visitor.visit_stmt(ast::Stmt::FunctionDef(function.clone()));
        Ok(visitor.found)
    }

    let suite = ast::Suite::parse(source, path).map_err(|error| ContractFailure {
        code: "frontend.python.parse-error",
        message: error.to_string(),
    })?;
    let helper_names = HELPERS
        .into_iter()
        .map(str::to_owned)
        .collect::<BTreeSet<_>>();
    let mut canonical = BTreeSet::new();
    for statement in &suite {
        let activated = match statement {
            ast::Stmt::FunctionDef(function) => function_uses_heap(function, &canonical)?,
            ast::Stmt::ClassDef(class) => {
                let class_shadows = class
                    .body
                    .iter()
                    .filter(|item| statement_binds_alias_name(item, &helper_names))
                    .flat_map(|item| {
                        helper_names
                            .iter()
                            .filter(|name| {
                                statement_binds_alias_name(item, &BTreeSet::from([(*name).clone()]))
                            })
                            .cloned()
                    })
                    .collect::<BTreeSet<_>>();
                let mut found = false;
                for item in &class.body {
                    let ast::Stmt::FunctionDef(function) = item else {
                        continue;
                    };
                    let active = canonical
                        .difference(&class_shadows)
                        .cloned()
                        .collect::<BTreeSet<_>>();
                    found |= function_uses_heap(function, &active)?;
                }
                found
            }
            _ => false,
        };
        if activated {
            return Ok(true);
        }

        for helper in &helper_names {
            if statement_binds_alias_name(statement, &BTreeSet::from([helper.clone()])) {
                canonical.remove(helper);
            }
        }
        if let ast::Stmt::ImportFrom(import) = statement
            && import.level.is_none_or(|level| level == 0_u32)
            && import
                .module
                .as_ref()
                .is_some_and(|module| module.as_str() == "nagini_contracts.contracts")
        {
            for alias in &import.names {
                if alias.name.as_str() == "*" {
                    canonical.extend(helper_names.iter().cloned());
                    continue;
                }
                let local = alias
                    .asname
                    .as_ref()
                    .map_or(alias.name.as_str(), |name| name.as_str());
                if local == alias.name.as_str() && helper_names.contains(local) {
                    canonical.insert(local.to_owned());
                }
            }
        }
    }
    Ok(false)
}

fn statement_has_heap_condition_feature(statement: &ast::Stmt) -> bool {
    match statement {
        ast::Stmt::FunctionDef(function) => function
            .body
            .iter()
            .any(statement_has_heap_condition_feature),
        ast::Stmt::ClassDef(class) => class.body.iter().any(statement_has_heap_condition_feature),
        ast::Stmt::If(statement) => {
            expression_has_heap_condition_feature(&statement.test)
                || statement
                    .body
                    .iter()
                    .any(statement_has_heap_condition_feature)
                || statement
                    .orelse
                    .iter()
                    .any(statement_has_heap_condition_feature)
        }
        _ => false,
    }
}

fn expression_has_heap_condition_feature(expression: &ast::Expr) -> bool {
    match expression {
        ast::Expr::Call(call) => matches!(
            call.func.as_ref(),
            ast::Expr::Attribute(attribute)
                if matches!(attribute.value.as_ref(), ast::Expr::Name(_))
        ),
        ast::Expr::BoolOp(boolean) => boolean
            .values
            .iter()
            .any(expression_has_heap_condition_feature),
        ast::Expr::Compare(compare) => {
            compare.ops.len() > 1
                || expression_has_heap_condition_feature(&compare.left)
                || compare
                    .comparators
                    .iter()
                    .any(expression_has_heap_condition_feature)
        }
        ast::Expr::UnaryOp(unary) => expression_has_heap_condition_feature(&unary.operand),
        ast::Expr::IfExp(conditional) => {
            expression_has_heap_condition_feature(&conditional.test)
                || expression_has_heap_condition_feature(&conditional.body)
                || expression_has_heap_condition_feature(&conditional.orelse)
        }
        ast::Expr::NamedExpr(named) => expression_has_heap_condition_feature(&named.value),
        _ => false,
    }
}

#[derive(Clone, Debug)]
struct HeapGenericClass {
    parameters: Vec<String>,
    specializations: BTreeMap<Vec<String>, HeapGenericSpecialization>,
    provider_template_placeholders: Vec<String>,
}

#[derive(Clone, Debug)]
struct ImportedHeapGenericClass {
    parameters: Vec<String>,
    placeholder_identities: Vec<String>,
    shape: ClassShape,
}

#[derive(Clone, Debug)]
struct HeapGenericSpecialization {
    arguments: Vec<ast::Expr>,
    concrete_class: String,
}

#[derive(Clone, Debug, Default)]
struct StaticHeapTyping {
    declaration_offsets: BTreeSet<u32>,
    variables: BTreeSet<String>,
    generic_classes: BTreeMap<String, HeapGenericClass>,
}

fn direct_typevar_call(expression: &ast::Expr) -> Option<(&str, &ast::ExprCall)> {
    let ast::Expr::Call(call) = expression else {
        return None;
    };
    match call.func.as_ref() {
        ast::Expr::Name(name) => Some((name.id.as_str(), call)),
        ast::Expr::Attribute(attribute) if attribute.attr.as_str() == "TypeVar" => {
            Some(("typing.TypeVar", call))
        }
        _ => None,
    }
}

fn generic_alias_parts(expression: &ast::Expr) -> Option<(&str, &ast::Expr)> {
    let ast::Expr::Subscript(subscript) = expression else {
        return None;
    };
    let ast::Expr::Name(origin) = subscript.value.as_ref() else {
        return None;
    };
    Some((origin.id.as_str(), subscript.slice.as_ref()))
}

fn generic_alias_arguments(expression: &ast::Expr) -> Option<(&str, Vec<&ast::Expr>)> {
    let (origin, slice) = generic_alias_parts(expression)?;
    let arguments = match slice {
        ast::Expr::Tuple(tuple) => tuple.elts.iter().collect(),
        argument => vec![argument],
    };
    Some((origin, arguments))
}

fn parsed_generic_alias_text(value: &str) -> Option<ast::Expr> {
    let expression = ast::Expr::parse(value, "<generic-annotation>").ok()?;
    generic_alias_parts(&expression)?;
    Some(expression)
}

struct GenericUseCollector<'a> {
    generic_arities: &'a BTreeMap<String, usize>,
    class_names: &'a BTreeSet<String>,
    arguments: BTreeMap<String, BTreeMap<Vec<String>, Vec<ast::Expr>>>,
    failure: Option<ContractFailure>,
}

impl GenericUseCollector<'_> {
    fn record(&mut self, origin: &str, arguments: &[&ast::Expr]) {
        if self.failure.is_some() || !self.generic_arities.contains_key(origin) {
            return;
        }
        let expected_arity = self.generic_arities[origin];
        if arguments.len() != expected_arity {
            self.failure = Some(ContractFailure {
                code: "frontend.python.heap.typevar-specialization-arity",
                message: format!(
                    "generic class {origin:?} declares {expected_arity} type parameters but this specialization supplies {} arguments",
                    arguments.len()
                ),
            });
            return;
        }
        let Some(argument_key) = arguments
            .iter()
            .map(|argument| generic_argument_key(argument))
            .collect::<Option<Vec<_>>>()
        else {
            self.failure = Some(ContractFailure {
                code: "frontend.python.heap.typevar-specialization-unsupported",
                message: format!(
                    "generic class {origin:?} requires closed supported concrete type arguments"
                ),
            });
            return;
        };
        let supported = arguments.iter().all(|argument| match argument {
            ast::Expr::Name(name) => {
                matches!(name.id.as_str(), "int" | "bool" | "str")
                    || self.class_names.contains(name.id.as_str())
            }
            ast::Expr::Subscript(subscript) => {
                matches!(subscript.value.as_ref(), ast::Expr::Name(name)
                    if matches!(name.id.as_str(), "List" | "PSeq"))
                    && matches!(subscript.slice.as_ref(), ast::Expr::Name(name) if name.id.as_str() == "int")
            }
            _ => false,
        });
        if !supported {
            self.failure = Some(ContractFailure {
                code: "frontend.python.heap.typevar-specialization-unsupported",
                message: format!(
                    "generic class {origin:?} requires concrete scalar, source-class, canonical List[int], or PSeq[int] arguments"
                ),
            });
            return;
        }
        self.arguments
            .entry(origin.to_owned())
            .or_default()
            .entry(argument_key)
            .or_insert_with(|| {
                arguments
                    .iter()
                    .map(|argument| (*argument).clone())
                    .collect()
            });
    }
}

fn generic_argument_key(argument: &ast::Expr) -> Option<String> {
    match argument {
        ast::Expr::Name(name) => Some(name.id.to_string()),
        ast::Expr::Subscript(subscript)
            if matches!(subscript.value.as_ref(), ast::Expr::Name(name)
                if matches!(name.id.as_str(), "List" | "PSeq"))
                && matches!(subscript.slice.as_ref(), ast::Expr::Name(name) if name.id.as_str() == "int") =>
        {
            let ast::Expr::Name(origin) = subscript.value.as_ref() else {
                unreachable!("generic collection argument guard established a name")
            };
            Some(format!("{}[int]", origin.id))
        }
        _ => None,
    }
}

impl Visitor for GenericUseCollector<'_> {
    fn visit_expr(&mut self, node: ast::Expr) {
        if let Some((origin, arguments)) = generic_alias_arguments(&node) {
            self.record(origin, &arguments);
        } else if let ast::Expr::Constant(constant) = &node
            && let ast::Constant::Str(value) = &constant.value
            && let Some(expression) = parsed_generic_alias_text(value)
            && let Some((origin, arguments)) = generic_alias_arguments(&expression)
        {
            self.record(origin, &arguments);
        }
        self.generic_visit_expr(node);
    }
}

struct ExpressionNameCollector<'a> {
    expected: &'a BTreeSet<String>,
    found: BTreeSet<String>,
}

impl Visitor for ExpressionNameCollector<'_> {
    fn visit_expr_name(&mut self, node: ast::ExprName) {
        if self.expected.contains(node.id.as_str()) {
            self.found.insert(node.id.to_string());
        }
    }
}

fn expression_typevars(expression: &ast::Expr, typevars: &BTreeSet<String>) -> BTreeSet<String> {
    let mut collector = ExpressionNameCollector {
        expected: typevars,
        found: BTreeSet::new(),
    };
    collector.visit_expr(expression.clone());
    collector.found
}

#[derive(Default)]
struct FirstResultCallOffset {
    offset: Option<u32>,
}

impl Visitor for FirstResultCallOffset {
    fn visit_expr_call(&mut self, node: ast::ExprCall) {
        if matches!(node.func.as_ref(), ast::Expr::Name(name) if name.id.as_str() == "Result")
            && node.args.is_empty()
            && node.keywords.is_empty()
        {
            let offset = u32::from(node.range.start());
            self.offset = Some(self.offset.map_or(offset, |current| current.min(offset)));
        }
        self.generic_visit_expr_call(node);
    }
}

fn postcondition_diagnostic_offset(expression: &ast::Expr, fallback: u32) -> u32 {
    let mut collector = FirstResultCallOffset::default();
    collector.visit_expr(expression.clone());
    collector.offset.unwrap_or(fallback)
}

fn collect_static_heap_typing(
    suite: &[ast::Stmt],
    type_comments: &BTreeMap<u32, String>,
    class_names: &BTreeSet<String>,
    source: &str,
    allow_provider_templates: bool,
) -> Result<StaticHeapTyping, ContractFailure> {
    let mut canonical_typevar_available = false;
    let mut canonical_generic_import_offsets = BTreeSet::new();
    let mut typevar_aliases = BTreeSet::new();
    let mut declaration_offsets = BTreeSet::new();
    let mut variables = BTreeSet::new();
    let mut variable_declaration_offsets = BTreeMap::new();
    let mut declaration_ranges = Vec::new();
    let mut import_ranges = Vec::new();

    for statement in suite {
        if let ast::Stmt::ImportFrom(import) = statement
            && import.level.is_none_or(|level| level == 0_u32)
            && import
                .module
                .as_ref()
                .is_some_and(|module| module.as_str() == "typing")
        {
            for alias in &import.names {
                match alias.name.as_str() {
                    "TypeVar" if alias.asname.is_none() => canonical_typevar_available = true,
                    "TypeVar" => {
                        typevar_aliases.insert(
                            alias
                                .asname
                                .as_ref()
                                .expect("aliased TypeVar import")
                                .to_string(),
                        );
                    }
                    "Generic" if alias.asname.is_none() => {
                        canonical_generic_import_offsets
                            .insert(u32::from(statement.range().start()));
                    }
                    _ => {}
                }
            }
            import_ranges.push((
                u32::from(statement.range().start()),
                u32::from(statement.range().end()),
            ));
            continue;
        }
        let ast::Stmt::Assign(assignment) = statement else {
            continue;
        };
        let Some((callee, call)) = direct_typevar_call(&assignment.value) else {
            continue;
        };
        if callee != "TypeVar" && callee != "typing.TypeVar" && !typevar_aliases.contains(callee) {
            continue;
        }
        if callee != "TypeVar" || !canonical_typevar_available {
            let alias = typevar_aliases.contains(callee) || callee == "typing.TypeVar";
            return fail(
                "frontend.python.heap.typevar-declaration-callee-unsupported",
                if alias {
                    "TypeVar declarations require the canonical unaliased imported TypeVar name"
                } else {
                    "TypeVar must be imported canonically from typing before its declaration"
                },
            );
        }
        let [ast::Expr::Name(target)] = assignment.targets.as_slice() else {
            return fail(
                "frontend.python.heap.typevar-declaration-target-unsupported",
                "TypeVar declarations require exactly one direct module name target",
            );
        };
        if !call.keywords.is_empty() || call.args.len() != 1 {
            return fail(
                "frontend.python.heap.typevar-declaration-arguments-unsupported",
                "TypeVar bounds, constraints, variance, defaults, and dynamic arguments are outside the resolved heap type IR",
            );
        }
        let ast::Expr::Constant(name) = &call.args[0] else {
            return fail(
                "frontend.python.heap.typevar-declaration-name-unsupported",
                "TypeVar declarations require one literal string name",
            );
        };
        let ast::Constant::Str(name) = &name.value else {
            return fail(
                "frontend.python.heap.typevar-declaration-name-unsupported",
                "TypeVar declarations require one literal string name",
            );
        };
        if name != target.id.as_str() {
            return fail(
                "frontend.python.heap.typevar-declaration-name-mismatch",
                format!(
                    "TypeVar target {:?} must match its literal declaration name {name:?}",
                    target.id
                ),
            );
        }
        if !variables.insert(target.id.to_string()) {
            return fail(
                "frontend.python.heap.typevar-binding-reassigned",
                format!("TypeVar {:?} is declared more than once", target.id),
            );
        }
        declaration_offsets.insert(u32::from(statement.range().start()));
        variable_declaration_offsets
            .insert(target.id.to_string(), u32::from(statement.range().start()));
        declaration_ranges.push((
            u32::from(statement.range().start()),
            u32::from(statement.range().end()),
        ));
    }

    let mut generic_parameters = BTreeMap::new();
    let class_definition_counts = suite
        .iter()
        .filter_map(|statement| match statement {
            ast::Stmt::ClassDef(class) => Some(class.name.to_string()),
            _ => None,
        })
        .fold(BTreeMap::<String, usize>::new(), |mut counts, name| {
            *counts.entry(name).or_default() += 1;
            counts
        });
    let mut allowed_static_ranges = import_ranges;
    allowed_static_ranges.extend(declaration_ranges);
    for statement in suite {
        let ast::Stmt::ClassDef(class) = statement else {
            continue;
        };
        let generic_bases = class
            .bases
            .iter()
            .filter_map(|base| {
                let (origin, parameters) = generic_alias_arguments(base)?;
                (origin == "Generic").then_some((base, parameters))
            })
            .collect::<Vec<_>>();
        let Some((base, parameter_expressions)) = generic_bases.first() else {
            continue;
        };
        if generic_bases.len() != 1 {
            return fail(
                "frontend.python.heap.typevar-generic-base-unsupported",
                "generic heap classes require exactly one canonical Generic base",
            );
        }
        let runtime_bases = class
            .bases
            .iter()
            .filter(|candidate| candidate.range() != base.range())
            .collect::<Vec<_>>();
        if !matches!(runtime_bases.as_slice(), [] | [ast::Expr::Name(_)]) {
            return fail(
                "frontend.python.heap.typevar-generic-base-unsupported",
                "generic heap classes support at most one direct nominal runtime base in addition to Generic",
            );
        }
        if !canonical_generic_import_offsets
            .iter()
            .any(|offset| *offset < u32::from(class.range.start()))
        {
            return fail(
                "frontend.python.heap.typevar-generic-base-unsupported",
                "generic heap classes require canonical unaliased Generic from typing before the class definition",
            );
        }
        if parameter_expressions.is_empty() {
            return fail(
                "frontend.python.heap.typevar-generic-base-unsupported",
                "generic heap classes require at least one direct TypeVar parameter",
            );
        }
        let mut parameters = Vec::with_capacity(parameter_expressions.len());
        let mut distinct_parameters = BTreeSet::new();
        for parameter in parameter_expressions {
            let ast::Expr::Name(parameter) = parameter else {
                return fail(
                    "frontend.python.heap.typevar-generic-base-unsupported",
                    "generic heap class parameters must be direct TypeVar names",
                );
            };
            if !variables.contains(parameter.id.as_str()) {
                return fail(
                    "frontend.python.heap.typevar-generic-parameter-undeclared",
                    format!(
                        "generic class {:?} names undeclared TypeVar {:?}",
                        class.name, parameter.id
                    ),
                );
            }
            if variable_declaration_offsets
                .get(parameter.id.as_str())
                .is_none_or(|offset| *offset >= u32::from(class.range.start()))
            {
                return fail(
                    "frontend.python.heap.typevar-generic-base-unsupported",
                    format!(
                        "generic class {:?} uses TypeVar {:?} before its declaration",
                        class.name, parameter.id
                    ),
                );
            }
            if !distinct_parameters.insert(parameter.id.to_string()) {
                return fail(
                    "frontend.python.heap.typevar-generic-parameter-duplicate",
                    format!(
                        "generic class {:?} repeats TypeVar {:?}",
                        class.name, parameter.id
                    ),
                );
            }
            parameters.push(parameter.id.to_string());
        }
        if class_definition_counts
            .get(class.name.as_str())
            .is_some_and(|count| *count != 1)
        {
            return fail(
                "frontend.python.heap.typevar-generic-class-redefined",
                format!("generic class {:?} is defined more than once", class.name),
            );
        }
        if generic_parameters
            .insert(class.name.to_string(), parameters)
            .is_some()
        {
            return fail(
                "frontend.python.heap.typevar-generic-class-redefined",
                format!("generic class {:?} is defined more than once", class.name),
            );
        }
        allowed_static_ranges.push((
            u32::from(base.range().start()),
            u32::from(base.range().end()),
        ));
    }

    let generic_arities = generic_parameters
        .iter()
        .map(|(class, parameters)| (class.clone(), parameters.len()))
        .collect::<BTreeMap<_, _>>();
    let mut uses = GenericUseCollector {
        generic_arities: &generic_arities,
        class_names,
        arguments: BTreeMap::new(),
        failure: None,
    };
    for statement in suite.iter().cloned() {
        uses.visit_stmt(statement);
    }
    if let Some(error) = uses.failure {
        return Err(error);
    }
    let mut generic_classes = BTreeMap::new();
    for (class, parameters) in generic_parameters {
        let mut arguments = uses.arguments.remove(&class).unwrap_or_default();
        let mut provider_template_placeholders = Vec::new();
        if arguments.is_empty() {
            if !allow_provider_templates {
                return fail(
                    "frontend.python.heap.typevar-specialization-unsupported",
                    format!(
                        "generic class {class:?} requires at least one concrete specialization in the closed source module"
                    ),
                );
            }
            provider_template_placeholders = parameters
                .iter()
                .enumerate()
                .map(|(index, _)| format!("__maledictus_generic_parameter_{class}_{index}"))
                .collect();
            if provider_template_placeholders
                .iter()
                .any(|placeholder| class_names.contains(placeholder))
            {
                return fail(
                    "frontend.python.heap.typevar-specialization-name-collision",
                    format!(
                        "generic provider class {class:?} collides with a reserved parameter placeholder"
                    ),
                );
            }
            let expressions = provider_template_placeholders
                .iter()
                .map(|placeholder| {
                    ast::ExprName {
                        range: rustpython_ast::text_size::TextRange::default(),
                        id: placeholder.as_str().into(),
                        ctx: ast::ExprContext::Load,
                    }
                    .into()
                })
                .collect::<Vec<ast::Expr>>();
            arguments.insert(provider_template_placeholders.clone(), expressions);
        }
        let mut specializations = BTreeMap::new();
        for (index, (argument_key, arguments)) in arguments.into_iter().enumerate() {
            let concrete_class = if index == 0 {
                class.clone()
            } else {
                format!("{class}__maledictus_specialization_{index}")
            };
            if concrete_class != class && class_names.contains(&concrete_class) {
                return fail(
                    "frontend.python.heap.typevar-specialization-name-collision",
                    format!(
                        "generated specialization class {concrete_class:?} collides with a source class"
                    ),
                );
            }
            specializations.insert(
                argument_key,
                HeapGenericSpecialization {
                    arguments,
                    concrete_class,
                },
            );
        }
        generic_classes.insert(
            class,
            HeapGenericClass {
                parameters,
                specializations,
                provider_template_placeholders,
            },
        );
    }

    fn validate_annotations(
        statements: &[ast::Stmt],
        active_parameters: Option<&[String]>,
        typing: &StaticHeapTyping,
        allowed_ranges: &mut Vec<(u32, u32)>,
    ) -> Result<(), ContractFailure> {
        fn validate_one(
            annotation: &ast::Expr,
            active_parameters: Option<&[String]>,
            typing: &StaticHeapTyping,
            allowed_ranges: &mut Vec<(u32, u32)>,
        ) -> Result<(), ContractFailure> {
            let used = expression_typevars(annotation, &typing.variables);
            let quoted_typevar = matches!(annotation, ast::Expr::Constant(constant)
                if matches!(&constant.value, ast::Constant::Str(value)
                    if value
                        .split(|character: char| !character.is_alphanumeric() && character != '_')
                        .any(|word| typing.variables.contains(word))));
            let active = active_parameters
                .into_iter()
                .flatten()
                .map(String::as_str)
                .collect::<BTreeSet<_>>();
            let parameters_are_local = used.iter().all(|name| active.contains(name.as_str()));
            fn supported_typevar_annotation_shape(
                annotation: &ast::Expr,
                all_typevars: &BTreeSet<String>,
                active: &BTreeSet<&str>,
            ) -> bool {
                match annotation {
                    ast::Expr::Name(name) if all_typevars.contains(name.id.as_str()) => {
                        active.contains(name.id.as_str())
                    }
                    ast::Expr::Subscript(subscript)
                        if matches!(subscript.value.as_ref(), ast::Expr::Name(name)
                            if matches!(name.id.as_str(), "Optional" | "Tuple")) =>
                    {
                        supported_typevar_annotation_shape(&subscript.slice, all_typevars, active)
                    }
                    ast::Expr::Tuple(tuple) => tuple.elts.iter().all(|element| {
                        supported_typevar_annotation_shape(element, all_typevars, active)
                    }),
                    other => expression_typevars(other, all_typevars).is_empty(),
                }
            }
            let supported_shape =
                supported_typevar_annotation_shape(annotation, &typing.variables, &active);
            if !used.is_empty() && (!parameters_are_local || !supported_shape) || quoted_typevar {
                return fail(
                    "frontend.python.heap.typevar-annotation-unsupported",
                    "TypeVar annotations are accepted as direct parameters or recursively inside Optional and fixed Tuple annotations of their declaring closed Generic class",
                );
            }
            allowed_ranges.push((
                u32::from(annotation.range().start()),
                u32::from(annotation.range().end()),
            ));
            Ok(())
        }

        for statement in statements {
            match statement {
                ast::Stmt::ClassDef(class) => {
                    let parameters = typing
                        .generic_classes
                        .get(class.name.as_str())
                        .map(|generic| generic.parameters.as_slice());
                    validate_annotations(&class.body, parameters, typing, allowed_ranges)?;
                }
                ast::Stmt::FunctionDef(function) => {
                    for argument in function
                        .args
                        .posonlyargs
                        .iter()
                        .chain(function.args.args.iter())
                        .chain(function.args.kwonlyargs.iter())
                    {
                        if let Some(annotation) = argument.def.annotation.as_deref() {
                            validate_one(annotation, active_parameters, typing, allowed_ranges)?;
                        }
                    }
                    if let Some(argument) = &function.args.vararg
                        && let Some(annotation) = argument.annotation.as_deref()
                    {
                        validate_one(annotation, active_parameters, typing, allowed_ranges)?;
                    }
                    if let Some(argument) = &function.args.kwarg
                        && let Some(annotation) = argument.annotation.as_deref()
                    {
                        validate_one(annotation, active_parameters, typing, allowed_ranges)?;
                    }
                    if let Some(annotation) = function.returns.as_deref() {
                        validate_one(annotation, active_parameters, typing, allowed_ranges)?;
                    }
                    validate_annotations(
                        &function.body,
                        active_parameters,
                        typing,
                        allowed_ranges,
                    )?;
                }
                ast::Stmt::AnnAssign(assignment) => {
                    validate_one(
                        &assignment.annotation,
                        active_parameters,
                        typing,
                        allowed_ranges,
                    )?;
                }
                ast::Stmt::If(branch) => {
                    validate_annotations(&branch.body, active_parameters, typing, allowed_ranges)?;
                    validate_annotations(
                        &branch.orelse,
                        active_parameters,
                        typing,
                        allowed_ranges,
                    )?;
                }
                ast::Stmt::While(branch) => {
                    validate_annotations(&branch.body, active_parameters, typing, allowed_ranges)?;
                    validate_annotations(
                        &branch.orelse,
                        active_parameters,
                        typing,
                        allowed_ranges,
                    )?;
                }
                ast::Stmt::For(branch) => {
                    validate_annotations(&branch.body, active_parameters, typing, allowed_ranges)?;
                    validate_annotations(
                        &branch.orelse,
                        active_parameters,
                        typing,
                        allowed_ranges,
                    )?;
                }
                ast::Stmt::Try(branch) => {
                    validate_annotations(&branch.body, active_parameters, typing, allowed_ranges)?;
                    validate_annotations(
                        &branch.orelse,
                        active_parameters,
                        typing,
                        allowed_ranges,
                    )?;
                    validate_annotations(
                        &branch.finalbody,
                        active_parameters,
                        typing,
                        allowed_ranges,
                    )?;
                    for handler in &branch.handlers {
                        let ast::ExceptHandler::ExceptHandler(handler) = handler;
                        validate_annotations(
                            &handler.body,
                            active_parameters,
                            typing,
                            allowed_ranges,
                        )?;
                    }
                }
                ast::Stmt::With(block) => {
                    validate_annotations(&block.body, active_parameters, typing, allowed_ranges)?;
                }
                _ => {}
            }
        }
        Ok(())
    }

    let typing = StaticHeapTyping {
        declaration_offsets,
        variables,
        generic_classes,
    };
    validate_annotations(suite, None, &typing, &mut allowed_static_ranges)?;
    for annotation in type_comments.values() {
        if typing.variables.iter().any(|name| {
            annotation
                .split(|character: char| !character.is_alphanumeric() && character != '_')
                .any(|word| word == name)
        }) {
            return fail(
                "frontend.python.heap.typevar-type-comment-unsupported",
                "TypeVar substitution in legacy type comments is outside the monomorphic generic fragment",
            );
        }
    }

    let mut forbidden_names = typing.variables.clone();
    forbidden_names.insert("TypeVar".to_owned());
    forbidden_names.insert("Generic".to_owned());
    forbidden_names.extend(typevar_aliases);
    fn contains_exported_typevar(expression: &ast::Expr, variables: &BTreeSet<String>) -> bool {
        match expression {
            ast::Expr::Constant(constant) => matches!(&constant.value, ast::Constant::Str(value)
                if variables.contains(value)),
            ast::Expr::List(list) => list
                .elts
                .iter()
                .any(|item| contains_exported_typevar(item, variables)),
            ast::Expr::Tuple(tuple) => tuple
                .elts
                .iter()
                .any(|item| contains_exported_typevar(item, variables)),
            ast::Expr::Set(set) => set
                .elts
                .iter()
                .any(|item| contains_exported_typevar(item, variables)),
            _ => false,
        }
    }
    for statement in suite {
        let ast::Stmt::Assign(assignment) = statement else {
            continue;
        };
        if assignment
            .targets
            .iter()
            .any(|target| matches!(target, ast::Expr::Name(name) if name.id.as_str() == "__all__"))
            && contains_exported_typevar(&assignment.value, &typing.variables)
        {
            return fail(
                "frontend.python.heap.typevar-runtime-use-unsupported",
                "static TypeVar bindings cannot be exported through __all__",
            );
        }
    }
    for token in lex(source, Mode::Module) {
        let Ok((Tok::Name { name }, range)) = token else {
            continue;
        };
        if forbidden_names.contains(&name) {
            let start = u32::from(range.start());
            let end = u32::from(range.end());
            if !allowed_static_ranges
                .iter()
                .any(|(allowed_start, allowed_end)| start >= *allowed_start && end <= *allowed_end)
            {
                return fail(
                    "frontend.python.heap.typevar-runtime-use-unsupported",
                    format!(
                        "static TypeVar binding {name:?} is read, rebound, shadowed, or exported in runtime syntax"
                    ),
                );
            }
        }
    }
    Ok(typing)
}

struct GenericMonomorphizer<'a> {
    generic_classes: &'a BTreeMap<String, HeapGenericClass>,
    active_specialization: Option<ActiveHeapGenericSpecialization>,
}

#[derive(Clone, Debug)]
struct ActiveHeapGenericSpecialization {
    substitutions: BTreeMap<String, ast::Expr>,
}

struct ScalarOldFieldRewriter<'a> {
    environment: &'a BTreeMap<String, Term>,
    object_classes: &'a BTreeMap<String, String>,
    classes: &'a BTreeMap<String, ClassShape>,
    entry_heap: u32,
    entry_mask: u32,
    occupied_names: BTreeSet<String>,
    replacements: BTreeMap<String, Term>,
    reads: Vec<HeapRead>,
}

impl Fold<rustpython_ast::text_size::TextRange> for ScalarOldFieldRewriter<'_> {
    type TargetU = rustpython_ast::text_size::TextRange;
    type Error = ContractFailure;
    type UserContext = ();

    fn will_map_user(&mut self, _user: &rustpython_ast::text_size::TextRange) {}

    fn map_user(
        &mut self,
        user: rustpython_ast::text_size::TextRange,
        _context: (),
    ) -> Result<rustpython_ast::text_size::TextRange, ContractFailure> {
        Ok(user)
    }

    fn fold_expr(&mut self, node: ast::Expr) -> Result<ast::Expr, ContractFailure> {
        if let ast::Expr::Call(call) = &node
            && matches!(call.func.as_ref(), ast::Expr::Name(name) if name.id.as_str() == "Old")
        {
            if !call.keywords.is_empty() {
                return fail(
                    "frontend.python.heap.old-expression-unsupported",
                    "Old(...) does not accept keyword arguments",
                );
            }
            let [ast::Expr::Attribute(attribute)] = call.args.as_slice() else {
                return fail(
                    "frontend.python.heap.old-expression-unsupported",
                    "Old(...) in a heap function requires one direct typed-local scalar field",
                );
            };
            let ast::Expr::Name(receiver_name) = attribute.value.as_ref() else {
                return fail(
                    "frontend.python.heap.old-expression-unsupported",
                    "Old(...) field receiver must be a direct typed local",
                );
            };
            let class_name = self
                .object_classes
                .get(receiver_name.id.as_str())
                .ok_or_else(|| ContractFailure {
                    code: "frontend.python.heap.old-expression-unsupported",
                    message: "Old(...) field receiver has no source nominal type".to_owned(),
                })?;
            let field_type = self.classes[class_name]
                .fields
                .get(attribute.attr.as_str())
                .ok_or_else(|| ContractFailure {
                    code: "frontend.python.heap.field-unknown",
                    message: format!("unknown field {class_name:?}.{}", attribute.attr),
                })?;
            if !matches!(field_type.sort, Sort::Int | Sort::Bool | Sort::String) {
                return fail(
                    "frontend.python.heap.old-expression-unsupported",
                    "Old(...) heap-function arithmetic supports scalar fields",
                );
            }
            let receiver = self.environment[receiver_name.id.as_str()].clone();
            let mut replacement_index = self.replacements.len();
            let replacement = loop {
                let candidate = format!("__maledictus_old_field_{replacement_index}");
                if !self.environment.contains_key(&candidate)
                    && !self.object_classes.contains_key(&candidate)
                    && !self.occupied_names.contains(&candidate)
                    && !self.replacements.contains_key(&candidate)
                {
                    break candidate;
                }
                replacement_index += 1;
            };
            self.replacements.insert(
                replacement.clone(),
                Term::FieldRead {
                    heap: self.entry_heap,
                    receiver: Box::new(receiver.clone()),
                    field: attribute.attr.to_string(),
                    sort: field_type.sort.clone(),
                },
            );
            self.reads.push(HeapRead {
                receiver,
                field: attribute.attr.to_string(),
                origin: HeapReadOrigin::OldEntry {
                    mask: self.entry_mask,
                },
            });
            return Ok(ast::ExprName {
                range: node.range(),
                id: replacement.into(),
                ctx: ast::ExprContext::Load,
            }
            .into());
        }
        rustpython_ast::fold::fold_expr(self, node)
    }
}

struct RaisedExceptionRewriter {
    replacement: String,
}

impl Fold<rustpython_ast::text_size::TextRange> for RaisedExceptionRewriter {
    type TargetU = rustpython_ast::text_size::TextRange;
    type Error = ContractFailure;
    type UserContext = ();

    fn will_map_user(&mut self, _user: &rustpython_ast::text_size::TextRange) {}

    fn map_user(
        &mut self,
        user: rustpython_ast::text_size::TextRange,
        _context: (),
    ) -> Result<rustpython_ast::text_size::TextRange, ContractFailure> {
        Ok(user)
    }

    fn fold_expr(&mut self, node: ast::Expr) -> Result<ast::Expr, ContractFailure> {
        if let ast::Expr::Call(call) = &node
            && matches!(call.func.as_ref(), ast::Expr::Name(name)
                if name.id.as_str() == "RaisedException")
        {
            if !call.args.is_empty() || !call.keywords.is_empty() {
                return fail(
                    "frontend.python.heap.raised-exception-arguments",
                    "RaisedException() does not accept arguments",
                );
            }
            return Ok(ast::ExprName {
                range: node.range(),
                id: self.replacement.clone().into(),
                ctx: ast::ExprContext::Load,
            }
            .into());
        }
        rustpython_ast::fold::fold_expr(self, node)
    }
}

impl Fold<rustpython_ast::text_size::TextRange> for GenericMonomorphizer<'_> {
    type TargetU = rustpython_ast::text_size::TextRange;
    type Error = ContractFailure;
    type UserContext = ();

    fn will_map_user(&mut self, _user: &rustpython_ast::text_size::TextRange) {}

    fn map_user(
        &mut self,
        user: rustpython_ast::text_size::TextRange,
        _context: (),
    ) -> Result<rustpython_ast::text_size::TextRange, ContractFailure> {
        Ok(user)
    }

    fn fold_stmt(&mut self, node: ast::Stmt) -> Result<ast::Stmt, ContractFailure> {
        match node {
            ast::Stmt::AnnAssign(assignment)
                if self.active_specialization.as_ref().is_some_and(|generic| {
                    annotation_is_active_generic_parameter(
                        assignment.annotation.as_ref(),
                        &generic.substitutions,
                    )
                }) && assignment.value.is_some() =>
            {
                let value = assignment.value.expect("annotated assignment value guard");
                Ok(ast::StmtAssign {
                    range: assignment.range,
                    targets: vec![self.fold_expr(*assignment.target)?],
                    value: Box::new(self.fold_expr(*value)?),
                    type_comment: None,
                }
                .into())
            }
            other => rustpython_ast::fold::fold_stmt(self, other),
        }
    }

    fn fold_stmt_function_def(
        &mut self,
        mut node: ast::StmtFunctionDef,
    ) -> Result<ast::StmtFunctionDef, ContractFailure> {
        if let Some(active) = &self.active_specialization {
            for argument in node
                .args
                .posonlyargs
                .iter_mut()
                .chain(node.args.args.iter_mut())
                .chain(node.args.kwonlyargs.iter_mut())
            {
                if argument
                    .def
                    .annotation
                    .as_deref()
                    .is_some_and(|annotation| {
                        annotation_is_optional_generic_parameter(annotation, &active.substitutions)
                    })
                    && matches!(argument.default.as_deref(), Some(ast::Expr::Constant(constant))
                        if constant.value == ast::Constant::None)
                {
                    // Optional[T] is narrowed to T for a closed specialization. Removing the
                    // None default makes omitted calls fail at ordinary argument binding, while
                    // explicit None fails the concrete type check.
                    argument.default = None;
                }
            }
        }
        rustpython_ast::fold::fold_stmt_function_def(self, node)
    }

    fn fold_expr(&mut self, node: ast::Expr) -> Result<ast::Expr, ContractFailure> {
        if let ast::Expr::Subscript(subscript) = &node
            && matches!(subscript.value.as_ref(), ast::Expr::Name(name)
                if name.id.as_str() == "Optional")
            && let ast::Expr::Name(parameter) = subscript.slice.as_ref()
            && let Some(active) = &self.active_specialization
            && let Some(argument) = active.substitutions.get(parameter.id.as_str())
        {
            return Ok(argument.clone());
        }
        if let ast::Expr::Name(name) = &node
            && let Some(argument) = self
                .active_specialization
                .as_ref()
                .and_then(|generic| generic.substitutions.get(name.id.as_str()))
        {
            return Ok(argument.clone());
        }
        if let Some((origin, arguments)) = generic_alias_arguments(&node)
            && let Some(generic) = self.generic_classes.get(origin)
            && let Some(argument_key) = arguments
                .iter()
                .map(|argument| generic_argument_key(argument))
                .collect::<Option<Vec<_>>>()
            && let Some(specialization) = generic.specializations.get(&argument_key)
        {
            return Ok(ast::ExprName {
                range: node.range(),
                id: specialization.concrete_class.as_str().into(),
                ctx: ast::ExprContext::Load,
            }
            .into());
        }
        if let ast::Expr::Constant(constant) = &node
            && let ast::Constant::Str(value) = &constant.value
            && let Some(expression) = parsed_generic_alias_text(value)
            && let Some((origin, arguments)) = generic_alias_arguments(&expression)
            && let Some(argument_key) = arguments
                .iter()
                .map(|argument| generic_argument_key(argument))
                .collect::<Option<Vec<_>>>()
            && let Some(specialization) = self
                .generic_classes
                .get(origin)
                .and_then(|generic| generic.specializations.get(&argument_key))
        {
            return Ok(ast::ExprConstant {
                range: constant.range,
                value: ast::Constant::Str(specialization.concrete_class.clone()),
                kind: constant.kind.clone(),
            }
            .into());
        }
        rustpython_ast::fold::fold_expr(self, node)
    }
}

fn annotation_is_optional_generic_parameter(
    annotation: &ast::Expr,
    substitutions: &BTreeMap<String, ast::Expr>,
) -> bool {
    matches!(annotation, ast::Expr::Subscript(subscript)
        if matches!(subscript.value.as_ref(), ast::Expr::Name(name)
            if name.id.as_str() == "Optional")
        && matches!(subscript.slice.as_ref(), ast::Expr::Name(name)
            if substitutions.contains_key(name.id.as_str())))
}

fn annotation_is_active_generic_parameter(
    annotation: &ast::Expr,
    substitutions: &BTreeMap<String, ast::Expr>,
) -> bool {
    matches!(annotation, ast::Expr::Name(name) if substitutions.contains_key(name.id.as_str()))
        || annotation_is_optional_generic_parameter(annotation, substitutions)
}

fn monomorphize_heap_generics(
    suite: Vec<ast::Stmt>,
    typing: &StaticHeapTyping,
) -> Result<Vec<ast::Stmt>, ContractFailure> {
    let mut monomorphizer = GenericMonomorphizer {
        generic_classes: &typing.generic_classes,
        active_specialization: None,
    };
    let mut concrete = Vec::new();
    for generic in typing.generic_classes.values() {
        for placeholder in &generic.provider_template_placeholders {
            let source = format!("class {placeholder}:\n    pass\n");
            let [statement] = ast::Suite::parse(&source, "<generic-provider-parameter>")
                .map_err(|error| ContractFailure {
                    code: "frontend.python.heap.typevar-template-internal-error",
                    message: error.to_string(),
                })?
                .try_into()
                .map_err(|_| ContractFailure {
                    code: "frontend.python.heap.typevar-template-internal-error",
                    message: "generic provider parameter did not parse as one class".to_owned(),
                })?;
            concrete.push(statement);
        }
    }
    for statement in suite {
        let ast::Stmt::ClassDef(class) = &statement else {
            concrete.push(monomorphizer.fold_stmt(statement)?);
            continue;
        };
        let Some(generic) = typing.generic_classes.get(class.name.as_str()) else {
            concrete.push(monomorphizer.fold_stmt(statement)?);
            continue;
        };
        for specialization in generic.specializations.values() {
            let mut specialized = class.clone();
            specialized.name = specialization.concrete_class.as_str().into();
            specialized
                .bases
                .retain(|base| !matches!(generic_alias_arguments(base), Some(("Generic", _))));
            monomorphizer.active_specialization = Some(ActiveHeapGenericSpecialization {
                substitutions: generic
                    .parameters
                    .iter()
                    .cloned()
                    .zip(specialization.arguments.iter().cloned())
                    .collect(),
            });
            concrete.push(ast::Stmt::ClassDef(
                monomorphizer.fold_stmt_class_def(specialized)?,
            ));
            monomorphizer.active_specialization = None;
        }
    }
    Ok(concrete)
}

fn imported_generic_argument_type(
    argument: &ast::Expr,
    class_names: &BTreeSet<String>,
) -> Option<(String, MethodType)> {
    match argument {
        ast::Expr::Name(name) if name.id.as_str() == "int" => {
            Some(("int".to_owned(), MethodType::scalar(Sort::Int)))
        }
        ast::Expr::Name(name) if name.id.as_str() == "bool" => {
            Some(("bool".to_owned(), MethodType::scalar(Sort::Bool)))
        }
        ast::Expr::Name(name) if name.id.as_str() == "str" => {
            Some(("str".to_owned(), MethodType::scalar(Sort::String)))
        }
        ast::Expr::Name(name) if class_names.contains(name.id.as_str()) => Some((
            name.id.to_string(),
            MethodType {
                sort: Sort::Reference,
                nominal_class: Some(name.id.to_string()),
                list_element_nominal_class: None,
                tuple_elements: Vec::new(),
                optional: false,
                accepts_any: false,
                accepts_any_tuple: false,
                callable: None,
            },
        )),
        _ => None,
    }
}

fn substitute_imported_generic_method_type(
    value: &mut MethodType,
    substitutions: &BTreeMap<String, MethodType>,
) {
    if let Some(name) = value.nominal_class.as_deref()
        && let Some(replacement) = substitutions.get(name)
    {
        let optional = value.optional;
        *value = replacement.clone();
        value.optional |= optional;
        return;
    }
    if let Some(name) = value.list_element_nominal_class.clone()
        && let Some(replacement) = substitutions.get(name.as_str())
    {
        value.list_element_nominal_class = replacement.nominal_class.clone();
    }
    for element in &mut value.tuple_elements {
        substitute_imported_generic_method_type(element, substitutions);
    }
    if let Some(callable) = value.callable.as_mut() {
        if let CallableParameters::Fixed(parameters) = &mut callable.parameters {
            for parameter in parameters {
                substitute_imported_generic_method_type(parameter, substitutions);
            }
        }
        substitute_imported_generic_method_type(&mut callable.result, substitutions);
    }
}

fn instantiate_imported_generic_shape(
    template: &ImportedHeapGenericClass,
    arguments: &[MethodType],
    concrete_name: &str,
    specialization_identity: &str,
) -> ClassShape {
    let substitutions = template
        .placeholder_identities
        .iter()
        .cloned()
        .zip(arguments.iter().cloned())
        .collect::<BTreeMap<_, _>>();
    let mut shape = template.shape.clone();
    shape.name = concrete_name.to_owned();
    shape.identity = specialization_identity.to_owned();
    for field in shape.fields.values_mut() {
        if let Some(name) = field.nominal_class.as_deref()
            && let Some(replacement) = substitutions.get(name)
        {
            field.sort = replacement.sort.clone();
            field.nominal_class = replacement.nominal_class.clone();
            field.optional |= replacement.optional;
        }
    }
    let substitute_summary = |summary: &mut MethodSummary| {
        for (_, parameter) in &mut summary.parameters {
            substitute_imported_generic_method_type(parameter, &substitutions);
        }
        if let Some((_, parameter)) = summary.var_args.as_mut() {
            substitute_imported_generic_method_type(parameter, &substitutions);
        }
        if let Some((_, parameter)) = summary.keyword_args.as_mut() {
            substitute_imported_generic_method_type(parameter, &substitutions);
        }
        substitute_imported_generic_method_type(&mut summary.return_type, &substitutions);
    };
    if let Some(constructor) = shape.constructor.as_mut() {
        for (_, parameter) in &mut constructor.parameters {
            substitute_imported_generic_method_type(parameter, &substitutions);
        }
        if let Some((_, parameter)) = constructor.var_args.as_mut() {
            substitute_imported_generic_method_type(parameter, &substitutions);
        }
        if let Some((_, parameter)) = constructor.keyword_args.as_mut() {
            substitute_imported_generic_method_type(parameter, &substitutions);
        }
    }
    for method in shape.methods.values_mut() {
        substitute_summary(method);
    }
    for property in shape.properties.values_mut() {
        substitute_summary(&mut property.getter);
        if let Some(setter) = property.setter.as_mut() {
            substitute_summary(&mut setter.method);
        }
    }
    shape
}

struct ImportedGenericExpressionFolder<'a> {
    bindings: &'a BTreeMap<String, ImportedHeapGenericClass>,
    class_names: &'a BTreeSet<String>,
    specializations: &'a mut BTreeMap<(String, Vec<String>), (String, ClassShape)>,
}

impl Fold<rustpython_ast::text_size::TextRange> for ImportedGenericExpressionFolder<'_> {
    type TargetU = rustpython_ast::text_size::TextRange;
    type Error = ContractFailure;
    type UserContext = ();

    fn will_map_user(&mut self, _user: &rustpython_ast::text_size::TextRange) {}

    fn map_user(
        &mut self,
        user: rustpython_ast::text_size::TextRange,
        _context: (),
    ) -> Result<rustpython_ast::text_size::TextRange, ContractFailure> {
        Ok(user)
    }

    fn fold_expr(&mut self, node: ast::Expr) -> Result<ast::Expr, ContractFailure> {
        if let ast::Expr::Subscript(subscript) = &node
            && let ast::Expr::Name(origin) = subscript.value.as_ref()
            && let Some(template) = self.bindings.get(origin.id.as_str())
        {
            let arguments = match subscript.slice.as_ref() {
                ast::Expr::Tuple(tuple) => tuple.elts.iter().collect::<Vec<_>>(),
                argument => vec![argument],
            };
            if arguments.len() != template.parameters.len() {
                return fail(
                    "frontend.python.heap.typevar-specialization-arity",
                    format!(
                        "imported generic class {:?} declares {} parameters but use supplies {}",
                        origin.id,
                        template.parameters.len(),
                        arguments.len()
                    ),
                );
            }
            let Some(arguments) = arguments
                .iter()
                .map(|argument| imported_generic_argument_type(argument, self.class_names))
                .collect::<Option<Vec<_>>>()
            else {
                return fail(
                    "frontend.python.heap.typevar-specialization-unsupported",
                    format!(
                        "imported generic class {:?} requires closed scalar or source nominal type arguments",
                        origin.id
                    ),
                );
            };
            let keys = arguments
                .iter()
                .map(|(key, _)| key.clone())
                .collect::<Vec<_>>();
            let binding_key = (origin.id.to_string(), keys.clone());
            let next_index = self
                .specializations
                .keys()
                .filter(|(binding, _)| binding == origin.id.as_str())
                .count();
            let (concrete_name, _) = self.specializations.entry(binding_key).or_insert_with(|| {
                let concrete_name = if next_index == 0 {
                    origin.id.to_string()
                } else {
                    format!(
                        "{}__maledictus_imported_specialization_{next_index}",
                        origin.id
                    )
                };
                let identity = format!("{}[{}]", template.shape.identity, keys.join(","));
                let method_types = arguments
                    .iter()
                    .map(|(_, value_type)| value_type.clone())
                    .collect::<Vec<_>>();
                let shape = instantiate_imported_generic_shape(
                    template,
                    &method_types,
                    &concrete_name,
                    &identity,
                );
                (concrete_name, shape)
            });
            return Ok(ast::ExprName {
                range: node.range(),
                id: concrete_name.as_str().into(),
                ctx: ast::ExprContext::Load,
            }
            .into());
        }
        if let ast::Expr::Name(name) = &node
            && self.bindings.contains_key(name.id.as_str())
        {
            return fail(
                "frontend.python.heap.typevar-raw-imported-generic-unsupported",
                format!(
                    "imported generic class {:?} requires an exact concrete specialization",
                    name.id
                ),
            );
        }
        rustpython_ast::fold::fold_expr(self, node)
    }
}

fn materialize_imported_heap_generics(
    suite: Vec<ast::Stmt>,
    imported_modules: &[ImportedHeapContractModule],
) -> Result<(Vec<ast::Stmt>, BTreeMap<String, ClassShape>), ContractFailure> {
    let imported_by_name = imported_modules
        .iter()
        .map(|module| (module.module.as_str(), module))
        .collect::<BTreeMap<_, _>>();
    let class_names = suite
        .iter()
        .filter_map(|statement| match statement {
            ast::Stmt::ClassDef(class) => Some(class.name.to_string()),
            _ => None,
        })
        .collect::<BTreeSet<_>>();
    let mut bindings = BTreeMap::<String, ImportedHeapGenericClass>::new();
    let mut specializations = BTreeMap::new();
    let mut concrete = Vec::with_capacity(suite.len());
    for statement in suite {
        if let ast::Stmt::ImportFrom(import) = &statement
            && let Some(imported) = import
                .module
                .as_ref()
                .and_then(|module| imported_by_name.get(module.as_str()))
        {
            for alias in &import.names {
                if alias.name.as_str() == "*" {
                    for (name, template) in &imported.generic_classes {
                        bindings.insert(name.clone(), template.clone());
                    }
                    continue;
                }
                let local_name = alias
                    .asname
                    .as_ref()
                    .map_or(alias.name.as_str(), |name| name.as_str());
                bindings.remove(local_name);
                if let Some(template) = imported.generic_classes.get(alias.name.as_str()) {
                    bindings.insert(local_name.to_owned(), template.clone());
                }
            }
            concrete.push(statement);
            continue;
        }
        let protected = bindings.keys().cloned().collect::<BTreeSet<_>>();
        if protected
            .iter()
            .any(|name| statement_binds_alias_name(&statement, &BTreeSet::from([name.clone()])))
        {
            return fail(
                "frontend.python.heap.typevar-imported-generic-rebound",
                "an imported generic binding is rebound or shadowed in the closed consumer module",
            );
        }
        let mut folder = ImportedGenericExpressionFolder {
            bindings: &bindings,
            class_names: &class_names,
            specializations: &mut specializations,
        };
        concrete.push(folder.fold_stmt(statement)?);
    }
    let shapes = specializations.into_values().collect();
    Ok((concrete, shapes))
}

struct ClosedConstructorFactoryInliner<'a> {
    factories: &'a BTreeMap<String, ast::Expr>,
    shadowed: BTreeSet<String>,
}

impl Fold<rustpython_ast::text_size::TextRange> for ClosedConstructorFactoryInliner<'_> {
    type TargetU = rustpython_ast::text_size::TextRange;
    type Error = ContractFailure;
    type UserContext = ();

    fn will_map_user(&mut self, _user: &rustpython_ast::text_size::TextRange) {}

    fn map_user(
        &mut self,
        user: rustpython_ast::text_size::TextRange,
        _context: (),
    ) -> Result<rustpython_ast::text_size::TextRange, ContractFailure> {
        Ok(user)
    }

    fn fold_expr(&mut self, node: ast::Expr) -> Result<ast::Expr, ContractFailure> {
        if let ast::Expr::Call(call) = &node
            && call.args.is_empty()
            && call.keywords.is_empty()
            && let ast::Expr::Name(function) = call.func.as_ref()
            && !self.shadowed.contains(function.id.as_str())
            && let Some(constructor) = self.factories.get(function.id.as_str())
        {
            return Ok(constructor.clone());
        }
        rustpython_ast::fold::fold_expr(self, node)
    }

    fn fold_stmt_function_def(
        &mut self,
        node: ast::StmtFunctionDef,
    ) -> Result<ast::StmtFunctionDef, ContractFailure> {
        // Nested declarations have their own Python lexical scope. The surrounding module heap
        // fragment rejects them independently; do not silently rewrite through that boundary.
        Ok(node)
    }
}

fn inline_closed_constructor_factories(
    suite: Vec<ast::Stmt>,
    class_names: &BTreeSet<String>,
) -> Result<Vec<ast::Stmt>, ContractFailure> {
    let candidates = suite
        .iter()
        .filter_map(|statement| {
            let ast::Stmt::FunctionDef(function) = statement else {
                return None;
            };
            if !function.decorator_list.is_empty()
                || !function.type_params.is_empty()
                || !function.args.posonlyargs.is_empty()
                || !function.args.args.is_empty()
                || function.args.vararg.is_some()
                || !function.args.kwonlyargs.is_empty()
                || function.args.kwarg.is_some()
            {
                return None;
            }
            let executable = function
                .body
                .iter()
                .filter(|statement| contract(statement).is_none() && !class_docstring(statement))
                .collect::<Vec<_>>();
            let [ast::Stmt::Return(returned)] = executable.as_slice() else {
                return None;
            };
            let expression = returned.value.as_deref()?;
            let ast::Expr::Call(call) = expression else {
                return None;
            };
            let ast::Expr::Name(class) = call.func.as_ref() else {
                return None;
            };
            class_names
                .contains(class.id.as_str())
                .then(|| (function.name.to_string(), expression.clone()))
        })
        .collect::<BTreeMap<_, _>>();
    let factories = candidates
        .into_iter()
        .filter(|(name, _)| {
            suite
                .iter()
                .filter(|statement| {
                    statement_binds_alias_name(statement, &BTreeSet::from([name.to_string()]))
                })
                .count()
                == 1
        })
        .collect::<BTreeMap<_, _>>();
    if factories.is_empty() {
        return Ok(suite);
    }
    suite
        .into_iter()
        .map(|statement| {
            let ast::Stmt::FunctionDef(mut function) = statement else {
                return Ok(statement);
            };
            let mut shadowed = callable_lexical_names(&function)?;
            if let Some(argument) = &function.args.vararg {
                shadowed.insert(argument.arg.to_string());
            }
            for argument in &function.args.kwonlyargs {
                shadowed.insert(argument.def.arg.to_string());
            }
            if let Some(argument) = &function.args.kwarg {
                shadowed.insert(argument.arg.to_string());
            }
            let mut inliner = ClosedConstructorFactoryInliner {
                factories: &factories,
                shadowed,
            };
            function.body = function
                .body
                .into_iter()
                .map(|statement| inliner.fold_stmt(statement))
                .collect::<Result<_, _>>()?;
            Ok(ast::Stmt::FunctionDef(function))
        })
        .collect()
}

#[derive(Clone, Debug)]
enum SourceTypeAlias {
    Class(String),
    Annotation(ast::Expr),
}

impl SourceTypeAlias {
    fn expression(&self, range: rustpython_ast::text_size::TextRange) -> ast::Expr {
        match self {
            Self::Class(name) => ast::ExprName {
                range,
                id: name.as_str().into(),
                ctx: ast::ExprContext::Load,
            }
            .into(),
            Self::Annotation(expression) => expression.clone(),
        }
    }
}

struct SourceTypeAliasRewriter<'a> {
    aliases: &'a BTreeMap<String, SourceTypeAlias>,
}

impl Fold<rustpython_ast::text_size::TextRange> for SourceTypeAliasRewriter<'_> {
    type TargetU = rustpython_ast::text_size::TextRange;
    type Error = ContractFailure;
    type UserContext = ();

    fn will_map_user(&mut self, _user: &rustpython_ast::text_size::TextRange) {}

    fn map_user(
        &mut self,
        user: rustpython_ast::text_size::TextRange,
        _context: (),
    ) -> Result<rustpython_ast::text_size::TextRange, ContractFailure> {
        Ok(user)
    }

    fn fold_expr(&mut self, node: ast::Expr) -> Result<ast::Expr, ContractFailure> {
        if let ast::Expr::Name(name) = &node
            && let Some(alias) = self.aliases.get(name.id.as_str())
        {
            return Ok(alias.expression(name.range));
        }
        rustpython_ast::fold::fold_expr(self, node)
    }
}

struct AliasCallRangeCollector<'a> {
    aliases: &'a BTreeSet<String>,
    ranges: Vec<(u32, u32)>,
}

#[derive(Default)]
struct DirectOptionalUseCollector {
    found: bool,
}

#[derive(Default)]
struct DirectUnionUseCollector {
    found: bool,
}

impl Visitor for DirectOptionalUseCollector {
    fn visit_expr_subscript(&mut self, node: ast::ExprSubscript) {
        if matches!(node.value.as_ref(), ast::Expr::Name(name)
            if name.id.as_str() == "Optional")
        {
            self.found = true;
        }
        self.generic_visit_expr_subscript(node);
    }
}

impl Visitor for DirectUnionUseCollector {
    fn visit_expr_subscript(&mut self, node: ast::ExprSubscript) {
        if matches!(node.value.as_ref(), ast::Expr::Name(name)
            if name.id.as_str() == "Union")
        {
            self.found = true;
        }
        self.generic_visit_expr_subscript(node);
    }
}

fn statement_uses_direct_optional(statement: &ast::Stmt) -> bool {
    fn expression_uses_optional(expression: &ast::Expr) -> bool {
        let mut collector = DirectOptionalUseCollector::default();
        collector.visit_expr(expression.clone());
        collector.found
    }
    if let ast::Stmt::FunctionDef(function) = statement {
        let argument_uses = function
            .args
            .posonlyargs
            .iter()
            .chain(function.args.args.iter())
            .chain(function.args.kwonlyargs.iter())
            .any(|argument| {
                argument
                    .def
                    .annotation
                    .as_deref()
                    .is_some_and(expression_uses_optional)
            })
            || function
                .args
                .vararg
                .as_deref()
                .and_then(|argument| argument.annotation.as_deref())
                .is_some_and(expression_uses_optional)
            || function
                .args
                .kwarg
                .as_deref()
                .and_then(|argument| argument.annotation.as_deref())
                .is_some_and(expression_uses_optional)
            || function
                .returns
                .as_deref()
                .is_some_and(expression_uses_optional);
        return argument_uses || function.body.iter().any(statement_uses_direct_optional);
    }
    if let ast::Stmt::ClassDef(class) = statement {
        return class.body.iter().any(statement_uses_direct_optional);
    }
    if let ast::Stmt::AnnAssign(assignment) = statement
        && expression_uses_optional(&assignment.annotation)
    {
        return true;
    }
    let mut collector = DirectOptionalUseCollector::default();
    collector.visit_stmt(statement.clone());
    collector.found
}

fn canonical_optional_import(statement: &ast::Stmt) -> bool {
    matches!(statement,
    ast::Stmt::ImportFrom(import)
        if import.level.is_none_or(|level| level == 0_u32)
            && import.module.as_ref().is_some_and(|module| module.as_str() == "typing")
            && import.names.iter().any(|imported| {
                (imported.name.as_str() == "Optional"
                    && imported.asname.as_ref().map_or("Optional", |name| name.as_str())
                        == "Optional")
                    || (imported.name.as_str() == "*" && imported.asname.is_none())
            }))
}

fn statement_uses_direct_union(statement: &ast::Stmt) -> bool {
    let mut collector = DirectUnionUseCollector::default();
    collector.visit_stmt(statement.clone());
    collector.found
}

fn canonical_union_import(statement: &ast::Stmt) -> bool {
    matches!(statement,
    ast::Stmt::ImportFrom(import)
        if import.level.is_none_or(|level| level == 0_u32)
            && import.module.as_ref().is_some_and(|module| module.as_str() == "typing")
            && import.names.iter().any(|imported| {
                (imported.name.as_str() == "Union"
                    && imported.asname.as_ref().map_or("Union", |name| name.as_str())
                        == "Union")
                    || (imported.name.as_str() == "*" && imported.asname.is_none())
            }))
}

fn validate_canonical_union_bindings(suite: &[ast::Stmt]) -> Result<(), ContractFailure> {
    let mut canonical_union = false;
    let mut union_semantics_used = false;
    let union_name = BTreeSet::from(["Union".to_owned()]);
    for statement in suite {
        let imports_canonical_union = canonical_union_import(statement);
        let binds_union = statement_binds_alias_name(statement, &union_name);
        let uses_union = statement_uses_direct_union(statement);
        if binds_union && !imports_canonical_union && (uses_union || union_semantics_used) {
            return fail(
                "frontend.python.heap.union-binding-reassigned",
                "typing.Union is protected from rebinding once it enters the verified type boundary",
            );
        }
        if uses_union && !canonical_union {
            return fail(
                "frontend.python.heap.union-binding-unresolved",
                "Union annotations require a preceding canonical `from typing import Union` binding",
            );
        }
        union_semantics_used |= uses_union;
        if imports_canonical_union {
            canonical_union = true;
        } else if binds_union {
            canonical_union = false;
        }
    }
    Ok(())
}

fn validate_canonical_optional_bindings(suite: &[ast::Stmt]) -> Result<(), ContractFailure> {
    let mut canonical_optional = false;
    let mut optional_semantics_used = false;
    let optional_name = BTreeSet::from(["Optional".to_owned()]);
    for statement in suite {
        let imports_canonical_optional = canonical_optional_import(statement);
        let binds_optional = statement_binds_alias_name(statement, &optional_name);
        let uses_optional = statement_uses_direct_optional(statement);
        if binds_optional
            && !imports_canonical_optional
            && (uses_optional || optional_semantics_used)
        {
            return fail(
                "frontend.python.heap.optional-binding-reassigned",
                "typing.Optional is protected from rebinding once it enters the verified type boundary",
            );
        }
        if uses_optional && !canonical_optional {
            return fail(
                "frontend.python.heap.optional-binding-unresolved",
                "Optional annotations and aliases require a preceding canonical `from typing import Optional` binding",
            );
        }
        optional_semantics_used |= uses_optional;
        if imports_canonical_optional {
            canonical_optional = true;
        } else if binds_optional {
            canonical_optional = false;
        }
    }
    Ok(())
}

fn annotation_uses_typing_name(expression: &ast::Expr, expected: &str) -> bool {
    struct Collector<'a> {
        expected: &'a str,
        found: bool,
    }
    impl Visitor for Collector<'_> {
        fn visit_expr_name(&mut self, node: ast::ExprName) {
            if node.id.as_str() == self.expected {
                self.found = true;
            }
        }
    }
    let mut collector = Collector {
        expected,
        found: false,
    };
    collector.visit_expr(expression.clone());
    collector.found
}

fn statement_annotation_uses_typing_name(statement: &ast::Stmt, expected: &str) -> bool {
    match statement {
        ast::Stmt::FunctionDef(function) => {
            function
                .args
                .posonlyargs
                .iter()
                .chain(function.args.args.iter())
                .chain(function.args.kwonlyargs.iter())
                .filter_map(|argument| argument.def.annotation.as_deref())
                .chain(
                    function
                        .args
                        .vararg
                        .as_deref()
                        .and_then(|argument| argument.annotation.as_deref()),
                )
                .chain(
                    function
                        .args
                        .kwarg
                        .as_deref()
                        .and_then(|argument| argument.annotation.as_deref()),
                )
                .chain(function.returns.as_deref())
                .any(|annotation| annotation_uses_typing_name(annotation, expected))
                || function
                    .body
                    .iter()
                    .any(|item| statement_annotation_uses_typing_name(item, expected))
        }
        ast::Stmt::ClassDef(class) => class
            .body
            .iter()
            .any(|item| statement_annotation_uses_typing_name(item, expected)),
        ast::Stmt::AnnAssign(assignment) => {
            annotation_uses_typing_name(&assignment.annotation, expected)
        }
        ast::Stmt::If(branch) => branch
            .body
            .iter()
            .chain(&branch.orelse)
            .any(|item| statement_annotation_uses_typing_name(item, expected)),
        ast::Stmt::For(loop_) => loop_
            .body
            .iter()
            .chain(&loop_.orelse)
            .any(|item| statement_annotation_uses_typing_name(item, expected)),
        ast::Stmt::While(loop_) => loop_
            .body
            .iter()
            .chain(&loop_.orelse)
            .any(|item| statement_annotation_uses_typing_name(item, expected)),
        ast::Stmt::Try(try_) => try_
            .body
            .iter()
            .chain(&try_.orelse)
            .chain(&try_.finalbody)
            .chain(try_.handlers.iter().flat_map(|handler| {
                let ast::ExceptHandler::ExceptHandler(handler) = handler;
                handler.body.iter()
            }))
            .any(|item| statement_annotation_uses_typing_name(item, expected)),
        ast::Stmt::With(with_) => with_
            .body
            .iter()
            .any(|item| statement_annotation_uses_typing_name(item, expected)),
        _ => false,
    }
}

fn canonical_typing_import(statement: &ast::Stmt, expected: &str) -> bool {
    matches!(statement,
    ast::Stmt::ImportFrom(import)
        if import.level.is_none_or(|level| level == 0_u32)
            && import.module.as_ref().is_some_and(|module| module.as_str() == "typing")
            && import.names.iter().any(|imported| {
                (imported.name.as_str() == expected
                    && imported.asname.as_ref().map_or(expected, |name| name.as_str())
                        == expected)
                    || (imported.name.as_str() == "*" && imported.asname.is_none())
            }))
}

fn validate_canonical_heap_typing_bindings(suite: &[ast::Stmt]) -> Result<(), ContractFailure> {
    for expected in ["Callable", "Any", "Tuple", "List"] {
        let names = BTreeSet::from([expected.to_owned()]);
        let mut canonical = false;
        let mut semantics_used = false;
        for statement in suite {
            let imports_canonical = canonical_typing_import(statement, expected);
            let binds = statement_binds_alias_name(statement, &names);
            let uses = statement_annotation_uses_typing_name(statement, expected);
            if binds && !imports_canonical && (uses || semantics_used) {
                return fail(
                    "frontend.python.heap.typing-binding-reassigned",
                    format!(
                        "typing.{expected} is protected from shadowing or rebinding once it enters the verified type boundary"
                    ),
                );
            }
            if uses && !canonical {
                return fail(
                    "frontend.python.heap.typing-binding-unresolved",
                    format!(
                        "{expected} annotations require a preceding canonical unaliased `from typing import {expected}` binding"
                    ),
                );
            }
            semantics_used |= uses;
            if imports_canonical {
                canonical = true;
            } else if binds {
                canonical = false;
            }
        }
    }
    Ok(())
}

fn verifier_intrinsic_class_bindings_before_statements(
    suite: &[ast::Stmt],
    imported_modules: &[ImportedHeapContractModule],
) -> BTreeMap<u32, BTreeMap<String, VerifierIntrinsicClassDescriptor>> {
    let imported_by_name = imported_modules
        .iter()
        .map(|module| (module.module.as_str(), module))
        .collect::<BTreeMap<_, _>>();
    let mut bindings = BTreeMap::<String, VerifierIntrinsicClassDescriptor>::new();
    let mut before_statement = BTreeMap::new();
    for statement in suite {
        before_statement.insert(u32::from(statement.range().start()), bindings.clone());
        let protected = bindings.keys().cloned().collect::<BTreeSet<_>>();
        for name in &protected {
            if statement_binds_alias_name(statement, &BTreeSet::from([name.clone()])) {
                bindings.remove(name);
            }
        }
        let ast::Stmt::ImportFrom(import) = statement else {
            continue;
        };
        let imported = import
            .module
            .as_ref()
            .and_then(|module| imported_by_name.get(module.as_str()));
        for alias in &import.names {
            if alias.name.as_str() == "*" {
                let Some(imported) = imported else {
                    bindings.clear();
                    continue;
                };
                for (name, descriptor) in &imported.verifier_intrinsic_classes {
                    bindings.insert(name.clone(), descriptor.clone());
                }
                continue;
            }
            let local_name = alias
                .asname
                .as_ref()
                .map_or(alias.name.as_str(), |name| name.as_str());
            bindings.remove(local_name);
            if let Some(descriptor) = imported
                .and_then(|module| module.verifier_intrinsic_classes.get(alias.name.as_str()))
            {
                bindings.insert(local_name.to_owned(), descriptor.clone());
            }
        }
    }
    before_statement
}

fn verifier_intrinsic_function_bindings_before_statements(
    suite: &[ast::Stmt],
    imported_modules: &[ImportedHeapContractModule],
) -> BTreeMap<u32, BTreeMap<String, VerifierIntrinsicFunctionDescriptor>> {
    let imported_by_name = imported_modules
        .iter()
        .map(|module| (module.module.as_str(), module))
        .collect::<BTreeMap<_, _>>();
    let mut bindings = BTreeMap::<String, VerifierIntrinsicFunctionDescriptor>::new();
    let mut before_statement = BTreeMap::new();
    for statement in suite {
        before_statement.insert(u32::from(statement.range().start()), bindings.clone());
        for name in bindings.keys().cloned().collect::<Vec<_>>() {
            if statement_binds_alias_name(statement, &BTreeSet::from([name.clone()])) {
                bindings.remove(&name);
            }
        }
        let ast::Stmt::ImportFrom(import) = statement else {
            continue;
        };
        let imported = import
            .module
            .as_ref()
            .and_then(|module| imported_by_name.get(module.as_str()));
        for alias in &import.names {
            if alias.name.as_str() == "*" {
                let Some(imported) = imported else {
                    bindings.clear();
                    continue;
                };
                bindings.extend(imported.verifier_intrinsics.clone());
                continue;
            }
            let local_name = alias
                .asname
                .as_ref()
                .map_or(alias.name.as_str(), |name| name.as_str());
            bindings.remove(local_name);
            if let Some(descriptor) =
                imported.and_then(|module| module.verifier_intrinsics.get(alias.name.as_str()))
            {
                bindings.insert(local_name.to_owned(), descriptor.clone());
            }
        }
    }
    before_statement
}

fn validate_optional_parameter_boundaries(
    suite: &[ast::Stmt],
    imported_modules: &[ImportedHeapContractModule],
) -> Result<(), ContractFailure> {
    let class_names = suite
        .iter()
        .filter_map(|statement| match statement {
            ast::Stmt::ClassDef(class) => Some(class.name.to_string()),
            _ => None,
        })
        .collect::<BTreeSet<_>>();

    fn validate_function(
        function: &ast::StmtFunctionDef,
        class_names: &BTreeSet<String>,
        generic_parameters: &[&str],
        intrinsic_classes: &BTreeMap<String, VerifierIntrinsicClassDescriptor>,
    ) -> Result<(), ContractFailure> {
        for argument in function
            .args
            .posonlyargs
            .iter()
            .chain(function.args.args.iter())
            .chain(function.args.kwonlyargs.iter())
        {
            let Some(ast::Expr::Subscript(optional)) = argument.def.annotation.as_deref() else {
                continue;
            };
            if !matches!(optional.value.as_ref(), ast::Expr::Name(name)
                if name.id.as_str() == "Optional")
            {
                continue;
            }
            let supported = matches!(optional.slice.as_ref(), ast::Expr::Name(inner)
                if class_names.contains(inner.id.as_str())
                    || generic_parameters.contains(&inner.id.as_str())
                    || intrinsic_classes.contains_key(inner.id.as_str()));
            if !supported {
                return fail(
                    "frontend.python.heap.type-unsupported",
                    "Optional parameter annotations require a source nominal reference type or the declaring closed Generic TypeVar",
                );
            }
        }
        Ok(())
    }

    let intrinsic_bindings =
        verifier_intrinsic_class_bindings_before_statements(suite, imported_modules);

    for statement in suite {
        let intrinsic_classes = intrinsic_bindings
            .get(&u32::from(statement.range().start()))
            .expect("intrinsic binding analysis records every statement prefix");
        match statement {
            ast::Stmt::FunctionDef(function) => {
                validate_function(function, &class_names, &[], intrinsic_classes)?;
            }
            ast::Stmt::ClassDef(class) => {
                let generic_parameters = class
                    .bases
                    .iter()
                    .find_map(|base| {
                        let (origin, parameters) = generic_alias_arguments(base)?;
                        if origin != "Generic" {
                            return None;
                        }
                        parameters
                            .into_iter()
                            .map(|parameter| match parameter {
                                ast::Expr::Name(parameter) => Some(parameter.id.as_str()),
                                _ => None,
                            })
                            .collect::<Option<Vec<_>>>()
                    })
                    .unwrap_or_default();
                for item in &class.body {
                    if let ast::Stmt::FunctionDef(function) = item {
                        validate_function(
                            function,
                            &class_names,
                            &generic_parameters,
                            intrinsic_classes,
                        )?;
                    }
                }
            }
            _ => {}
        }
    }
    Ok(())
}

impl Visitor for AliasCallRangeCollector<'_> {
    fn visit_expr_call(&mut self, node: ast::ExprCall) {
        let direct_constructor = matches!(node.func.as_ref(), ast::Expr::Name(name)
            if self.aliases.contains(name.id.as_str()));
        let isinstance_alias = matches!(node.func.as_ref(), ast::Expr::Name(name)
            if name.id.as_str() == "isinstance")
            && matches!(node.args.get(1), Some(ast::Expr::Name(name))
                if self.aliases.contains(name.id.as_str()));
        if direct_constructor || isinstance_alias {
            self.ranges
                .push((u32::from(node.range.start()), u32::from(node.range.end())));
        }
        self.generic_visit_expr_call(node);
    }
}

fn push_annotation_range(expression: &ast::Expr, ranges: &mut Vec<(u32, u32)>) {
    ranges.push((
        u32::from(expression.range().start()),
        u32::from(expression.range().end()),
    ));
}

fn collect_annotation_ranges(statements: &[ast::Stmt], ranges: &mut Vec<(u32, u32)>) {
    for statement in statements {
        match statement {
            ast::Stmt::FunctionDef(function) => {
                for argument in function
                    .args
                    .posonlyargs
                    .iter()
                    .chain(function.args.args.iter())
                    .chain(function.args.kwonlyargs.iter())
                {
                    if let Some(annotation) = argument.def.annotation.as_deref() {
                        push_annotation_range(annotation, ranges);
                    }
                }
                if let Some(argument) = function.args.vararg.as_deref()
                    && let Some(annotation) = argument.annotation.as_deref()
                {
                    push_annotation_range(annotation, ranges);
                }
                if let Some(argument) = function.args.kwarg.as_deref()
                    && let Some(annotation) = argument.annotation.as_deref()
                {
                    push_annotation_range(annotation, ranges);
                }
                if let Some(annotation) = function.returns.as_deref() {
                    push_annotation_range(annotation, ranges);
                }
                collect_annotation_ranges(&function.body, ranges);
            }
            ast::Stmt::ClassDef(class) => collect_annotation_ranges(&class.body, ranges),
            ast::Stmt::AnnAssign(assignment) => {
                push_annotation_range(&assignment.annotation, ranges)
            }
            ast::Stmt::If(branch) => {
                collect_annotation_ranges(&branch.body, ranges);
                collect_annotation_ranges(&branch.orelse, ranges);
            }
            ast::Stmt::For(loop_) => {
                collect_annotation_ranges(&loop_.body, ranges);
                collect_annotation_ranges(&loop_.orelse, ranges);
            }
            ast::Stmt::While(loop_) => {
                collect_annotation_ranges(&loop_.body, ranges);
                collect_annotation_ranges(&loop_.orelse, ranges);
            }
            ast::Stmt::Try(try_) => {
                collect_annotation_ranges(&try_.body, ranges);
                collect_annotation_ranges(&try_.orelse, ranges);
                collect_annotation_ranges(&try_.finalbody, ranges);
                for handler in &try_.handlers {
                    let ast::ExceptHandler::ExceptHandler(handler) = handler;
                    collect_annotation_ranges(&handler.body, ranges);
                }
            }
            ast::Stmt::With(with_) => collect_annotation_ranges(&with_.body, ranges),
            _ => {}
        }
    }
}

fn statement_binds_alias_name(statement: &ast::Stmt, aliases: &BTreeSet<String>) -> bool {
    aliases.iter().any(|name| match statement {
        ast::Stmt::FunctionDef(function) => function.name.as_str() == name,
        ast::Stmt::ClassDef(class) => class.name.as_str() == name,
        ast::Stmt::Assign(assignment) => assignment
            .targets
            .iter()
            .any(|target| assignment_target_binds_name(target, name)),
        ast::Stmt::AnnAssign(assignment) => assignment_target_binds_name(&assignment.target, name),
        ast::Stmt::AugAssign(assignment) => assignment_target_binds_name(&assignment.target, name),
        ast::Stmt::Import(import) => import.names.iter().any(|alias| {
            alias.asname.as_ref().map_or_else(
                || alias.name.as_str().split('.').next().unwrap_or_default(),
                |alias| alias.as_str(),
            ) == name
        }),
        ast::Stmt::ImportFrom(import) => import.names.iter().any(|alias| {
            alias
                .asname
                .as_ref()
                .map_or(alias.name.as_str(), |alias| alias.as_str())
                == name
        }),
        _ => false,
    })
}

fn resolve_source_type_aliases(
    suite: Vec<ast::Stmt>,
    source: &str,
) -> Result<Vec<ast::Stmt>, ContractFailure> {
    let mut aliases = BTreeMap::<String, SourceTypeAlias>::new();
    let mut alias_declaration_offsets = BTreeMap::<String, u32>::new();
    let mut alias_statement_offsets = BTreeSet::new();
    let mut allowed_ranges = Vec::new();
    let mut bound_classes = BTreeSet::new();
    let mut canonical_list = false;
    let mut canonical_optional = false;
    let mut optional_semantics_used = false;

    for statement in &suite {
        let imports_canonical_optional = canonical_optional_import(statement);
        let binds_optional =
            statement_binds_alias_name(statement, &BTreeSet::from(["Optional".to_owned()]));
        let uses_optional = statement_uses_direct_optional(statement);
        if binds_optional
            && !imports_canonical_optional
            && (uses_optional || optional_semantics_used)
        {
            return fail(
                "frontend.python.heap.optional-binding-reassigned",
                "typing.Optional is protected from rebinding once it enters the verified type boundary",
            );
        }
        if uses_optional && !canonical_optional {
            return fail(
                "frontend.python.heap.optional-binding-unresolved",
                "Optional annotations and aliases require a preceding canonical `from typing import Optional` binding",
            );
        }
        optional_semantics_used |= uses_optional;
        let alias_names = aliases.keys().cloned().collect::<BTreeSet<_>>();
        if statement_binds_alias_name(statement, &alias_names) {
            return fail(
                "frontend.python.heap.type-alias-reassigned",
                "source-local type aliases are immutable after declaration",
            );
        }
        match statement {
            ast::Stmt::ImportFrom(import)
                if import.level.is_none_or(|level| level == 0_u32)
                    && import
                        .module
                        .as_ref()
                        .is_some_and(|module| module.as_str() == "typing") =>
            {
                for imported in &import.names {
                    if imported.name.as_str() == "*" && imported.asname.is_none() {
                        canonical_list = true;
                        canonical_optional = true;
                        continue;
                    }
                    let binding = imported
                        .asname
                        .as_ref()
                        .map_or(imported.name.as_str(), |name| name.as_str());
                    if binding == "List" {
                        canonical_list = imported.name.as_str() == "List";
                    }
                    if binding == "Optional" {
                        canonical_optional = imported.name.as_str() == "Optional";
                    }
                }
            }
            ast::Stmt::ClassDef(class) => {
                bound_classes.insert(class.name.to_string());
                if class.name.as_str() == "List" {
                    canonical_list = false;
                }
                if class.name.as_str() == "Optional" {
                    canonical_optional = false;
                }
            }
            ast::Stmt::Assign(assignment) if assignment.targets.len() == 1 => {
                let ast::Expr::Name(target) = &assignment.targets[0] else {
                    continue;
                };
                if target.id.as_str() == "List" {
                    canonical_list = false;
                }
                if target.id.as_str() == "Optional" {
                    canonical_optional = false;
                }
                let resolved = match assignment.value.as_ref() {
                    ast::Expr::Name(name) if bound_classes.contains(name.id.as_str()) => {
                        Some(SourceTypeAlias::Class(name.id.to_string()))
                    }
                    ast::Expr::Name(name) => aliases.get(name.id.as_str()).and_then(|alias| {
                        matches!(alias, SourceTypeAlias::Class(_)).then(|| alias.clone())
                    }),
                    ast::Expr::Subscript(subscript)
                        if (canonical_list || canonical_optional)
                            && matches!(subscript.value.as_ref(), ast::Expr::Name(name)
                                if (name.id.as_str() == "List" && canonical_list)
                                    || (name.id.as_str() == "Optional" && canonical_optional)) =>
                    {
                        let constructor = match subscript.value.as_ref() {
                            ast::Expr::Name(name) => name.id.to_string(),
                            _ => {
                                unreachable!("match guard established a direct typing constructor")
                            }
                        };
                        let class = match subscript.slice.as_ref() {
                            ast::Expr::Name(name) if bound_classes.contains(name.id.as_str()) => {
                                Some(name.id.to_string())
                            }
                            ast::Expr::Name(name) => {
                                aliases.get(name.id.as_str()).and_then(|alias| match alias {
                                    SourceTypeAlias::Class(class) => Some(class.clone()),
                                    SourceTypeAlias::Annotation(_) => None,
                                })
                            }
                            _ => None,
                        };
                        class.map(|class| {
                            SourceTypeAlias::Annotation(
                                ast::ExprSubscript {
                                    range: subscript.range,
                                    value: Box::new(
                                        ast::ExprName {
                                            range: subscript.value.range(),
                                            id: constructor.into(),
                                            ctx: ast::ExprContext::Load,
                                        }
                                        .into(),
                                    ),
                                    slice: Box::new(
                                        ast::ExprName {
                                            range: subscript.slice.range(),
                                            id: class.into(),
                                            ctx: ast::ExprContext::Load,
                                        }
                                        .into(),
                                    ),
                                    ctx: ast::ExprContext::Load,
                                }
                                .into(),
                            )
                        })
                    }
                    _ => None,
                };
                if let Some(resolved) = resolved {
                    aliases.insert(target.id.to_string(), resolved);
                    alias_declaration_offsets
                        .insert(target.id.to_string(), u32::from(statement.range().start()));
                    alias_statement_offsets.insert(u32::from(statement.range().start()));
                    allowed_ranges.push((
                        u32::from(statement.range().start()),
                        u32::from(statement.range().end()),
                    ));
                }
            }
            _ => {}
        }
    }
    if aliases.is_empty() {
        return Ok(suite);
    }
    collect_annotation_ranges(&suite, &mut allowed_ranges);
    let alias_names = aliases.keys().cloned().collect::<BTreeSet<_>>();
    let mut call_ranges = AliasCallRangeCollector {
        aliases: &alias_names,
        ranges: Vec::new(),
    };
    for statement in suite.iter().cloned() {
        call_ranges.visit_stmt(statement);
    }
    allowed_ranges.extend(call_ranges.ranges);
    for token in lex(source, Mode::Module) {
        let Ok((Tok::Name { name }, range)) = token else {
            continue;
        };
        let Some(declaration_offset) = alias_declaration_offsets.get(&name) else {
            continue;
        };
        let start = u32::from(range.start());
        let end = u32::from(range.end());
        if start < *declaration_offset
            || !allowed_ranges
                .iter()
                .any(|(allowed_start, allowed_end)| start >= *allowed_start && end <= *allowed_end)
        {
            return fail(
                "frontend.python.heap.type-alias-runtime-use-unsupported",
                format!(
                    "source-local type alias {name:?} escapes its ordered annotation, constructor, or isinstance boundary"
                ),
            );
        }
    }
    let mut rewriter = SourceTypeAliasRewriter { aliases: &aliases };
    suite
        .into_iter()
        .filter(|statement| {
            !alias_statement_offsets.contains(&u32::from(statement.range().start()))
        })
        .map(|statement| rewriter.fold_stmt(statement))
        .collect()
}

fn constructor_attribute_annotation_text(
    annotation: &ast::Expr,
) -> Result<String, ContractFailure> {
    match annotation {
        ast::Expr::Name(name) => Ok(name.id.to_string()),
        ast::Expr::Constant(constant) => match &constant.value {
            ast::Constant::Str(name) => Ok(name.clone()),
            _ => fail(
                "frontend.python.heap.constructor-field-annotation-unsupported",
                "constructor attribute annotations require a direct or quoted source type",
            ),
        },
        ast::Expr::Subscript(subscript)
            if matches!(subscript.value.as_ref(), ast::Expr::Name(name)
                if name.id.as_str() == "Optional") =>
        {
            Ok(format!(
                "Optional[{}]",
                constructor_attribute_annotation_text(&subscript.slice)?
            ))
        }
        _ => fail(
            "frontend.python.heap.constructor-field-annotation-unsupported",
            "constructor attribute annotations require int, bool, a source class, or Optional[source class]",
        ),
    }
}

fn normalize_constructor_attribute_annotations(
    statements: &mut [ast::Stmt],
) -> Result<(), ContractFailure> {
    for statement in statements {
        match statement {
            ast::Stmt::AnnAssign(assignment)
                if assignment.value.is_some()
                    && matches!(assignment.target.as_ref(), ast::Expr::Attribute(_)) =>
            {
                let type_comment = constructor_attribute_annotation_text(&assignment.annotation)?;
                let range = assignment.range;
                let target = assignment.target.clone();
                let value = assignment
                    .value
                    .clone()
                    .expect("annotated constructor assignment value guard");
                *statement = ast::StmtAssign {
                    range,
                    targets: vec![*target],
                    value,
                    type_comment: Some(type_comment),
                }
                .into();
            }
            ast::Stmt::If(branch) => {
                normalize_constructor_attribute_annotations(&mut branch.body)?;
                normalize_constructor_attribute_annotations(&mut branch.orelse)?;
            }
            _ => {}
        }
    }
    Ok(())
}

fn normalize_constructor_field_annotations(
    mut suite: Vec<ast::Stmt>,
) -> Result<Vec<ast::Stmt>, ContractFailure> {
    for statement in &mut suite {
        let ast::Stmt::ClassDef(class) = statement else {
            continue;
        };
        for item in &mut class.body {
            let ast::Stmt::FunctionDef(method) = item else {
                continue;
            };
            if method.name.as_str() == "__init__" {
                normalize_constructor_attribute_annotations(&mut method.body)?;
            }
        }
    }
    Ok(suite)
}

