pub(crate) fn verify_sif_termination_module(
    source: &str,
    path: &str,
    information_flow: InformationFlowVerificationProfile,
) -> Result<Option<HeapContractVerification>, ContractFailure> {
    let suite = ast::Suite::parse(source, path).map_err(|error| ContractFailure {
        code: "frontend.python.parse-error",
        message: error.to_string(),
    })?;
    let Some(analysis) =
        python_sif_contracts::analyze_termination_channels(&suite, information_flow)?
    else {
        return Ok(None);
    };
    let mut obligations = analysis
        .failures
        .iter()
        .map(|failure| {
            let marker = match failure.kind {
                python_sif_contracts::SifTerminationFailureKind::ConditionNotLow => {
                    "sif-termination-condition-not-low"
                }
                python_sif_contracts::SifTerminationFailureKind::NotLowEvent => {
                    "sif-termination-not-lowevent"
                }
                python_sif_contracts::SifTerminationFailureKind::ConditionNotTight => {
                    "sif-termination-condition-not-tight"
                }
                python_sif_contracts::SifTerminationFailureKind::LoopPromiseNotKept => {
                    "sif-loop-promise-not-kept"
                }
                python_sif_contracts::SifTerminationFailureKind::CallConditionNotLow => {
                    "sif-call-termination-condition-not-low"
                }
                python_sif_contracts::SifTerminationFailureKind::CallerUnsatisfied => {
                    "sif-termination-caller-unsatisfied"
                }
            };
            obligation(
                format!("{}:{marker}:{}", failure.owner, failure.offset),
                Vec::new(),
                Term::Bool { value: false },
                path,
                source,
                failure.offset,
            )
        })
        .collect::<Vec<_>>();
    obligations.extend(analysis.methods.iter().map(|method| {
        obligation(
            format!("{method}:sif-termination-channel-checked"),
            Vec::new(),
            Term::Bool { value: true },
            path,
            source,
            0,
        )
    }));
    let obligations = obligations
        .iter()
        .map(|obligation| {
            discharge(obligation).map_err(|message| ContractFailure {
                code: "solver.translation-failed",
                message,
            })
        })
        .collect::<Result<Vec<_>, _>>()?;
    let passed = obligations.iter().all(ObligationResult::satisfied);
    Ok(Some(HeapContractVerification {
        schema: "maledictus-python-sif-termination-channels/v1".to_owned(),
        path: path.to_owned(),
        methods: analysis.methods,
        obligations,
        passed,
    }))
}

