    #[test]
    fn inferred_method_results_exclude_non_total_or_effectful_methods() {
        let tuple = ast::Expr::parse("(left, right)", "inferred-result.py").unwrap();
        let no_fields = BTreeSet::new();
        let no_parameter_fields = BTreeMap::new();
        assert_eq!(
            inferred_verified_method_result(
                Some(&tuple),
                true,
                &no_fields,
                &no_parameter_fields,
                false,
            ),
            Some(tuple.clone())
        );

        assert!(
            inferred_verified_method_result(None, true, &no_fields, &no_parameter_fields, false,)
                .is_none(),
            "multi-return methods have no verified single-return relation"
        );
        assert!(
            inferred_verified_method_result(
                Some(&tuple),
                false,
                &no_fields,
                &no_parameter_fields,
                false,
            )
            .is_none(),
            "permission-changing methods must remain modular"
        );
        assert!(
            inferred_verified_method_result(
                Some(&tuple),
                true,
                &BTreeSet::from(["value".to_owned()]),
                &no_parameter_fields,
                false,
            )
            .is_none(),
            "receiver mutations prohibit exact result inference"
        );
        assert!(
            inferred_verified_method_result(
                Some(&tuple),
                true,
                &no_fields,
                &BTreeMap::from([("other".to_owned(), BTreeSet::from(["value".to_owned()]))]),
                false,
            )
            .is_none(),
            "parameter mutations prohibit exact result inference"
        );
        assert!(
            inferred_verified_method_result(
                Some(&tuple),
                true,
                &no_fields,
                &no_parameter_fields,
                true,
            )
            .is_none(),
            "methods with exceptional outcomes prohibit exact result inference"
        );

        for partial_or_effectful in ["helper(value)", "values[0]", "1 // divisor"] {
            let expression = ast::Expr::parse(partial_or_effectful, "inferred-result.py").unwrap();
            assert!(
                inferred_verified_method_result(
                    Some(&expression),
                    true,
                    &no_fields,
                    &no_parameter_fields,
                    false,
                )
                .is_none(),
                "{partial_or_effectful:?} must not produce an inferred result relation"
            );
        }
    }

    #[test]
    fn typevars_are_static_and_never_enter_module_or_captured_runtime_state() {
        let source = "from typing import Generic, TypeVar\nT = TypeVar('T')\nclass Box(Generic[T]):\n    value: T\ndef run() -> None:\n    box = Box[int](1)\n";
        let suite = ast::Suite::parse(source, "static_typevar.py").unwrap();
        let comments = collect_heap_type_comments(source).unwrap();
        let class_names = ["Box".to_owned()].into_iter().collect();
        let typing =
            collect_static_heap_typing(&suite, &comments, &class_names, source, false).unwrap();
        let suite = monomorphize_heap_generics(suite, &typing).unwrap();
        let globals = derive_immutable_heap_module_globals(
            &suite,
            source,
            HeapModuleGlobalDerivationContext {
                metadata: Some(HeapModuleMetadata {
                    name: "__main__",
                    file: "static_typevar.py",
                }),
                type_comments: &comments,
                class_names: &class_names,
                scalar_functions: &BTreeMap::new(),
                static_typing: &typing,
                proof_irrelevant_bindings: &BTreeSet::new(),
                imported_modules: &[],
            },
        )
        .unwrap();

        assert!(!globals.final_values.contains_key("T"));
        assert!(
            globals
                .before_statement
                .values()
                .all(|environment| !environment.contains_key("T"))
        );
        assert!(!globals.passive_reference_candidates.contains("T"));
    }

    #[test]
    fn static_typevars_refuse_shadowed_late_duplicate_quoted_and_exported_forms() {
        let collect = |source: &str| {
            let suite = ast::Suite::parse(source, "typevar_adversary.py").unwrap();
            let comments = collect_heap_type_comments(source).unwrap();
            let class_names = suite
                .iter()
                .filter_map(|statement| match statement {
                    ast::Stmt::ClassDef(class) => Some(class.name.to_string()),
                    _ => None,
                })
                .collect();
            collect_static_heap_typing(&suite, &comments, &class_names, source, false)
        };

        let shadowed = collect("from typing import Generic, TypeVar\nT = TypeVar('T')\nGeneric = object\nclass Box(Generic[T]):\n    value: T\nbox = Box[int](1)\n")
            .unwrap_err();
        assert_eq!(
            shadowed.code,
            "frontend.python.heap.typevar-runtime-use-unsupported"
        );

        let late = collect("from typing import TypeVar\nT = TypeVar('T')\nclass Box(Generic[T]):\n    value: T\nfrom typing import Generic\nbox = Box[int](1)\n")
            .unwrap_err();
        assert_eq!(
            late.code,
            "frontend.python.heap.typevar-generic-base-unsupported"
        );

        let late_typevar = collect("from typing import Generic, TypeVar\nclass Box(Generic[T]):\n    value: T\nT = TypeVar('T')\nbox = Box[int](1)\n")
            .unwrap_err();
        assert_eq!(
            late_typevar.code,
            "frontend.python.heap.typevar-generic-base-unsupported"
        );

        let duplicate = collect("from typing import Generic, TypeVar\nT = TypeVar('T')\nclass Box(Generic[T]):\n    value: T\nclass Box(Generic[T]):\n    value: T\nbox = Box[int](1)\n")
            .unwrap_err();
        assert_eq!(
            duplicate.code,
            "frontend.python.heap.typevar-generic-class-redefined"
        );

        let replaced = collect("from typing import Generic, TypeVar\nT = TypeVar('T')\nclass Box(Generic[T]):\n    value: T\nclass Box:\n    value: int\nbox = Box[int](1)\n")
            .unwrap_err();
        assert_eq!(
            replaced.code,
            "frontend.python.heap.typevar-generic-class-redefined"
        );

        let quoted = collect("from typing import Generic, TypeVar\nT = TypeVar('T')\nclass Box(Generic[T]):\n    value: 'T'\nbox = Box[int](1)\n")
            .unwrap_err();
        assert_eq!(
            quoted.code,
            "frontend.python.heap.typevar-annotation-unsupported"
        );

        let quoted_nested = collect("from typing import Generic, TypeVar\nT = TypeVar('T')\nclass Box(Generic[T]):\n    value: 'list[T]'\nbox = Box[int](1)\n")
            .unwrap_err();
        assert_eq!(
            quoted_nested.code,
            "frontend.python.heap.typevar-annotation-unsupported"
        );

        let multiple_specializations = collect("from typing import Generic, TypeVar\nT = TypeVar('T')\nclass Box(Generic[T]):\n    value: T\nints = Box[int](1)\nbools = Box[bool](True)\n")
            .unwrap();
        assert_eq!(
            multiple_specializations.generic_classes["Box"]
                .specializations
                .keys()
                .cloned()
                .collect::<Vec<_>>(),
            [vec!["bool".to_owned()], vec!["int".to_owned()]]
        );

        let exported = collect("from typing import Generic, TypeVar\nT = TypeVar('T')\nclass Box(Generic[T]):\n    value: T\nbox = Box[int](1)\n__all__ = ['T']\n")
            .unwrap_err();
        assert_eq!(
            exported.code,
            "frontend.python.heap.typevar-runtime-use-unsupported"
        );
    }

