    #[test]
    fn class_neutral_function_obligations_ignore_unrelated_class_order_and_identity() {
        let verify = |classes: &str, path: &str| {
            let source = format!(
                "from nagini_contracts.contracts import *\n\n{classes}\ndef run(flag: bool) -> None:\n    Requires(flag == flag)\n    Assert(flag == flag)\n"
            );
            verify_heap_module(&source, path, &["run".to_owned()]).unwrap()
        };
        let left = verify(
            "class Alpha:\n    FIRST = 1\n\nclass Omega:\n    LAST = 2\n\n",
            "class_order_left.py",
        );
        let right = verify(
            "class Zzzzz:\n    LAST = 2\n\nclass Bbbbb:\n    FIRST = 1\n\n",
            "class_order_right.py",
        );
        assert!(left.passed, "{:#?}", left.obligations);
        assert!(right.passed, "{:#?}", right.obligations);
        let run_outcomes = |verification: &HeapContractVerification| {
            verification
                .obligations
                .iter()
                .filter(|item| item.id.starts_with("run:"))
                .map(|item| (item.id.clone(), item.status))
                .collect::<Vec<_>>()
        };
        assert_eq!(run_outcomes(&left), run_outcomes(&right));
    }

