    #[test]
    fn refuses_invalid_nominal_field_return_types_and_dynamic_paths() {
        for (name, source, code) in [
            (
                "wrong_nominal",
                "from nagini_contracts.contracts import *\n\nclass Expected:\n    pass\n\nclass Actual:\n    pass\n\nclass Holder:\n    value: Actual\n\n    def get(self) -> Expected:\n        Requires(Acc(self.value))\n        return self.value\n",
                "frontend.python.heap.return-nominal-type-mismatch",
            ),
            (
                "optional_result",
                "from typing import Optional\nfrom nagini_contracts.contracts import *\n\nclass Child:\n    pass\n\nclass Holder:\n    child: Optional[Child]\n\n    def get(self) -> Child:\n        Requires(Acc(self.child))\n        return self.child\n",
                "frontend.python.heap.return-nominal-type-optional",
            ),
            (
                "scalar_result",
                "from nagini_contracts.contracts import *\n\nclass Child:\n    pass\n\nclass Holder:\n    value: int\n\n    def get(self) -> Child:\n        Requires(Acc(self.value))\n        return self.value\n",
                "frontend.python.heap.return-nominal-type-unresolved",
            ),
            (
                "dynamic_call",
                "class Child:\n    pass\n\nclass Holder:\n    def get(self) -> Child:\n        return Child()\n",
                "frontend.python.heap.return-nominal-type-unresolved",
            ),
            (
                "optional_receiver",
                "from typing import Optional\nfrom nagini_contracts.contracts import *\n\nclass Parent:\n    pass\n\nclass Child:\n    parent: Parent\n\nclass Holder:\n    child: Optional[Child]\n\n    def get(self) -> Parent:\n        Requires(Acc(self.child))\n        Requires(Acc(self.child.parent))\n        return self.child.parent\n",
                "frontend.python.heap.return-nominal-type-optional-receiver",
            ),
        ] {
            let error = verify_heap_module(source, &format!("{name}.py"), &[]).unwrap_err();
            assert_eq!(error.code, code, "{name}: {error:?}");
        }
    }

