    #[test]
    fn refuses_unsupported_result_identity_shapes_without_generic_reference_lowering() {
        for (name, source) in [
            (
                "optional",
                "from typing import Optional\nfrom nagini_contracts.contracts import *\n\nclass Child:\n    pass\n\nclass Holder:\n    child: Optional[Child]\n    fallback: Child\n    def get(self) -> Child:\n        Requires(Acc(self.fallback))\n        Ensures(Result() is self.child)\n        return self.fallback\n",
            ),
            (
                "nested",
                "from nagini_contracts.contracts import *\n\nclass Leaf:\n    pass\n\nclass Child:\n    leaf: Leaf\n\nclass Holder:\n    child: Child\n    fallback: Leaf\n    def get(self) -> Leaf:\n        Requires(Acc(self.fallback))\n        Ensures(Result() is self.child.leaf)\n        return self.fallback\n",
            ),
            (
                "call",
                "from nagini_contracts.contracts import *\n\nclass Child:\n    pass\n\nclass Holder:\n    child: Child\n    @Pure\n    def selected(self) -> Child:\n        Requires(Acc(self.child))\n        return self.child\n    def get(self) -> Child:\n        Requires(Acc(self.child))\n        Ensures(Result() is self.selected())\n        return self.child\n",
            ),
            (
                "field_property_collision",
                "from nagini_contracts.contracts import *\n\nclass Leaf:\n    pass\n\nclass Holder:\n    selected: Leaf\n    backing: Leaf\n    @property\n    def selected(self) -> Leaf:\n        Requires(Acc(self.backing))\n        return self.backing\n    def get(self) -> Leaf:\n        Requires(Acc(self.backing))\n        Ensures(Result() is self.selected)\n        return self.backing\n",
            ),
        ] {
            let error =
                verify_heap_module(source, &format!("result_identity_{name}.py"), &[]).unwrap_err();
            assert_eq!(
                error.code, "frontend.python.heap.result-identity-expression-unsupported",
                "{name}: {error:?}"
            );
        }
    }

