    #[test]
    fn refuses_inherited_and_explicit_super_constructor_exceptions_at_field_boundary() {
        for (name, derived_body) in [
            ("inherited", "    pass\n"),
            (
                "explicit_super",
                "    def __init__(self) -> None:\n        super().__init__()\n",
            ),
        ] {
            let source = format!(
                "from nagini_contracts.contracts import *\n\nclass Failure(Exception):\n    pass\n\nclass Base:\n    def __init__(self) -> None:\n        Exsures(Failure, True)\n\nclass Derived(Base):\n{derived_body}\nclass Holder:\n    item: Derived\n\n    def __init__(self) -> None:\n        self.item = Derived()\n"
            );
            let error = verify_heap_module(&source, &format!("{name}.py"), &[]).unwrap_err();
            assert_eq!(
                error.code,
                "frontend.python.heap.constructor-field-exceptional-unsupported"
            );
        }
    }

