    #[test]
    fn proves_behaviorally_compatible_override() {
        let result = verify_heap_module(
            "from nagini_contracts.contracts import *\n\nclass Base:\n    value: int\n\n    def get(self) -> int:\n        Requires(Acc(self.value))\n        Requires(self.value > 0)\n        Ensures(Acc(self.value))\n        Ensures(Result() > 0)\n        return self.value\n\nclass Derived(Base):\n    def get(self) -> int:\n        Requires(Acc(self.value))\n        Ensures(Acc(self.value))\n        Ensures(Result() == self.value)\n        return self.value\n",
            "compatible_override.py",
            &[],
        )
        .unwrap();
        assert!(result.passed, "{:#?}", result.obligations);
        assert!(
            result.obligations.iter().any(|item| {
                item.id.contains("precondition-not-strengthened") && item.satisfied()
            })
        );
        assert!(
            result
                .obligations
                .iter()
                .any(|item| { item.id.contains("postcondition-not-weakened") && item.satisfied() })
        );
    }

