    #[test]
    fn heap_selection_checks_only_the_selected_class_body_and_override() {
        let selected = BTreeSet::from(["SubB".to_owned()]);
        let result = verify_heap_module_selection_for_conformance(
            "from nagini_contracts.contracts import *\n\nclass SuperB:\n    def some_method(self, value: int) -> int:\n        Requires(value > 9)\n        Ensures(Result() > 9)\n        return value\n\nclass SubB(SuperB):\n    def some_method(self, value: int) -> int:\n        Requires(value > 10)\n        Ensures(Result() > 10)\n        return value + 5\n\nclass SubSubB(SubB):\n    def some_method(self, value: int) -> int:\n        Requires(value > 11)\n        Ensures(Result() > 10)\n        return value + 5\n",
            "select/SubB.py",
            &selected,
        )
        .unwrap();
        let refuted = result
            .obligations
            .iter()
            .filter(|item| item.status == ObligationStatus::Refuted)
            .collect::<Vec<_>>();
        assert_eq!(refuted.len(), 1);
        assert_eq!(
            refuted[0].id,
            "override:SubB.some_method:SuperB:precondition-not-strengthened"
        );
        assert_eq!(result.methods, ["SubB.some_method"]);
    }

