    #[test]
    fn checks_non_neutral_permission_contracts_at_override_boundaries() {
        let result = verify_heap_module(
            "from nagini_contracts.contracts import *\n\nclass Data:\n    value: int\n\nclass Base:\n    def read(self, item: Data) -> int:\n        Requires(Acc(item.value, 1 / 2))\n        Ensures(Acc(item.value, 1 / 4))\n        return item.value\n\nclass Compatible(Base):\n    def read(self, item: Data) -> int:\n        Requires(Acc(item.value, 1 / 2))\n        Ensures(Acc(item.value, 1 / 4))\n        return item.value + 1\n\nclass WeakerPre(Base):\n    def read(self, item: Data) -> int:\n        Requires(Acc(item.value, 1 / 4))\n        Ensures(Acc(item.value, 1 / 4))\n        return item.value + 1\n\nclass StrongerPost(Base):\n    def read(self, item: Data) -> int:\n        Requires(Acc(item.value, 1 / 2))\n        Ensures(Acc(item.value, 1 / 2))\n        return item.value + 1\n\nclass BadPre(Base):\n    def read(self, item: Data) -> int:\n        Requires(Acc(item.value, 2 / 3))\n        Ensures(Acc(item.value, 2 / 3))\n        return item.value + 1\n\nclass BadPost(Base):\n    def read(self, item: Data) -> int:\n        Requires(Acc(item.value, 1 / 2))\n        Ensures(Acc(item.value, 1 / 8))\n        return item.value + 1\n",
            "permission_override.py",
            &[],
        )
        .unwrap();
        assert!(!result.passed);
        let refuted = result
            .obligations
            .iter()
            .filter(|item| item.status == ObligationStatus::Refuted)
            .map(|item| item.id.as_str())
            .collect::<Vec<_>>();
        assert_eq!(
            refuted,
            [
                "override:BadPre.read:Base:precondition-not-strengthened:permission",
                "override:BadPost.read:Base:postcondition-not-weakened:permission",
            ]
        );
        assert!(result.obligations.iter().any(|item| {
            item.id == "override:Compatible.read:Base:postcondition-not-weakened:permission"
                && item.satisfied()
        }));
    }

