    #[test]
    fn constructors_may_temporarily_store_null_but_must_establish_nonoptional_fields() {
        let result = verify_heap_module(
            "from typing import Optional\nfrom nagini_contracts.contracts import *\n\nclass B:\n    pass\n\nclass C:\n    pass\n\nclass OptionalHolder:\n    def __init__(self) -> None:\n        self.b = None  # type: Optional[B]\n        self.c = None  # type: Optional[C]\n\n    def compare(self) -> None:\n        Requires(Acc(self.b) and Acc(self.c))\n        Assert(self.b is not self.c)\n\nclass RequiredHolder:\n    def __init__(self) -> None:\n        Ensures(Acc(self.b))\n        Ensures(Acc(self.c))\n        self.b = None  # type: B\n        self.c = None  # type: C\n\n    def compare(self) -> None:\n        Requires(Acc(self.b) and Acc(self.c))\n        Assert(self.b is not self.c)\n",
            "constructor_nullability.py",
            &[],
        )
        .unwrap();
        assert!(!result.passed);
        let refuted = result
            .obligations
            .iter()
            .filter(|item| item.status == ObligationStatus::Refuted)
            .map(|item| item.id.as_str())
            .collect::<Vec<_>>();
        assert_eq!(refuted.len(), 2);
        assert!(
            refuted
                .iter()
                .any(|item| item.starts_with("OptionalHolder.compare:assert:"))
        );
        assert!(
            refuted.contains(&"RequiredHolder.__init__:postcondition:implicit-non-null-fields")
        );
    }

