    #[test]
    fn immutable_heap_globals_are_source_ordered_typed_and_lexically_scoped() {
        let result = verify_heap_module(
            "from nagini_contracts.contracts import *\n\nBASE: int = 40\nOFFSET = 2\n\nclass Cell:\n    value: int\n\n    def __init__(self) -> None:\n        Ensures(Acc(self.value))\n        Ensures(self.value == BASE + OFFSET)\n        self.value = BASE + OFFSET\n\n    def answer(self) -> int:\n        Requires(Acc(self.value))\n        Requires(self.value == BASE + OFFSET)\n        Ensures(Acc(self.value))\n        Ensures(Result() == BASE + OFFSET)\n        return self.value\n\ndef run() -> None:\n    cell = Cell()\n    observed = cell.answer()\n    Assert(observed == 42)\n",
            "heap_globals.py",
            &[],
        )
        .unwrap();
        assert!(result.passed, "{:#?}", result.obligations);

        let forward = verify_heap_module(
            "LATER = FUTURE\nFUTURE = 1\n\nclass Marker:\n    pass\n",
            "forward_global.py",
            &[],
        )
        .unwrap_err();
        assert_eq!(forward.code, "frontend.python.name.unresolved");

        let mismatch = verify_heap_module(
            "VALUE: bool = 1\n\nclass Marker:\n    pass\n",
            "global_mismatch.py",
            &[],
        )
        .unwrap_err();
        assert_eq!(
            mismatch.code,
            "frontend.python.heap.module-global-type-mismatch"
        );

        let duplicate = verify_heap_module(
            "VALUE = 1\nVALUE = 2\n\nclass Marker:\n    pass\n",
            "global_duplicate.py",
            &[],
        )
        .unwrap_err();
        assert_eq!(
            duplicate.code,
            "frontend.python.heap.module-binding-reassigned"
        );

        let collision = verify_heap_module(
            "Marker = 1\n\nclass Marker:\n    pass\n",
            "global_class_collision.py",
            &[],
        )
        .unwrap_err();
        assert_eq!(
            collision.code,
            "frontend.python.heap.module-binding-reassigned"
        );

        let lexical_local = verify_heap_module(
            "from nagini_contracts.contracts import *\n\nVALUE = 1\n\nclass Marker:\n    pass\n\ndef invalid() -> None:\n    Assert(VALUE == 1)\n    VALUE = 2\n",
            "lexical_local.py",
            &[],
        )
        .unwrap_err();
        assert_eq!(lexical_local.code, "frontend.python.name.unresolved");

        let explicit_global = verify_heap_module(
            "VALUE = 1\n\nclass Marker:\n    pass\n\ndef invalid() -> None:\n    global VALUE\n    VALUE = 2\n",
            "explicit_global.py",
            &[],
        )
        .unwrap_err();
        assert_eq!(
            explicit_global.code,
            "frontend.python.heap.module-global-mutation-unsupported"
        );
    }

    #[test]
    fn builtin_type_object_aliases_are_class_typed_and_shadow_aware() {
        let alias = verify_heap_module("TextIO = int\n", "builtin_type_alias.py", &[])
            .expect("a class-valued immutable module binding is a nonempty verified module");
        assert!(alias.passed);

        let source = "from provider import int\nTextIO = int\n";
        let suite = ast::Suite::parse(source, "import_shadowed_builtin_type.py").unwrap();
        let error = match derive_immutable_heap_module_globals(
            &suite,
            source,
            HeapModuleGlobalDerivationContext {
                metadata: Some(HeapModuleMetadata {
                    name: "__main__",
                    file: "import_shadowed_builtin_type.py",
                }),
                type_comments: &BTreeMap::new(),
                class_names: &BTreeSet::new(),
                scalar_functions: &BTreeMap::new(),
                static_typing: &StaticHeapTyping::default(),
                proof_irrelevant_bindings: &BTreeSet::new(),
                imported_modules: &[],
            },
        ) {
            Err(error) => error,
            Ok(_) => panic!("an imported int binding must shadow the canonical builtin"),
        };
        assert_eq!(error.code, "frontend.python.name.unresolved");

        let shadowed = ["int".to_owned()].into_iter().collect();
        let int_name = ast::Suite::parse("Alias = int\n", "shadow_probe.py").unwrap();
        let ast::Stmt::Assign(assignment) = &int_name[0] else {
            unreachable!()
        };
        assert_eq!(
            canonical_heap_builtin_type_object(&assignment.value, &BTreeSet::new()),
            Some(Term::ClassLiteral {
                name: "builtins::int".to_owned()
            })
        );
        assert_eq!(
            canonical_heap_builtin_type_object(&assignment.value, &shadowed),
            None
        );
    }

