    #[test]
    fn pure_scalar_callables_preserve_recursion_prefix_and_contract_boundaries() {
        let before_definition = verify_heap_module(
            "from nagini_contracts.contracts import *\n\nclass Marker:\n    pass\n\nEARLY = later(1)\n\n@Pure\ndef later(value: int) -> int:\n    return value\n",
            "pure_source_prefix.py",
            &[],
        )
        .unwrap();
        assert!(!before_definition.passed);
        assert!(before_definition.obligations.iter().any(|obligation| {
            obligation.id == "module:undefined-call:EARLY"
                && obligation.status == ObligationStatus::Refuted
        }));

        for source in [
            "from nagini_contracts.contracts import *\n\n@Pure\ndef recurse(value: int) -> int:\n    return recurse(value)\n",
            "from nagini_contracts.contracts import *\n\n@Pure\ndef left(value: int) -> int:\n    return right(value)\n\n@Pure\ndef right(value: int) -> int:\n    return left(value)\n",
        ] {
            let error = verify_heap_module(source, "pure_recursion.py", &[]).unwrap_err();
            assert_eq!(error.code, "frontend.python.heap.recursive-function-call");
        }

        let precondition = verify_heap_module(
            "from nagini_contracts.contracts import *\n\n@Pure\ndef positive(value: int) -> int:\n    Requires(value > 0)\n    return value\n\nclass Marker:\n    pass\n\ndef run() -> None:\n    observed = positive(1)\n",
            "pure_precondition_call.py",
            &[],
        )
        .unwrap();
        assert!(precondition.passed, "{:#?}", precondition.obligations);

        let violated_precondition = verify_heap_module(
            "from nagini_contracts.contracts import *\n\n@Pure\ndef positive(value: int) -> int:\n    Requires(value > 0)\n    return value\n\nclass Marker:\n    pass\n\ndef run() -> None:\n    observed = positive(0)\n",
            "pure_precondition_violation.py",
            &[],
        )
        .unwrap();
        assert!(!violated_precondition.passed);
        assert!(violated_precondition.obligations.iter().any(|obligation| {
            obligation.id.contains(":call-precondition:positive:")
                && obligation.status == ObligationStatus::Refuted
        }));

        let false_postcondition = verify_heap_module(
            "from nagini_contracts.contracts import *\n\n@Pure\ndef wrong(value: int) -> int:\n    Ensures(Result() == value + 1)\n    return value\n",
            "pure_false_postcondition.py",
            &[],
        )
        .unwrap();
        assert!(!false_postcondition.passed);
        assert!(false_postcondition.obligations.iter().any(|obligation| {
            obligation.id == "wrong:postcondition:0"
                && obligation.status == ObligationStatus::Refuted
        }));

        let mutable_capture = verify_heap_module(
            "from nagini_contracts.contracts import *\n\nOFFSET = 1\n\n@Pure\ndef read() -> int:\n    return OFFSET\n\nOFFSET = 2\n",
            "pure_mutable_capture.py",
            &[],
        )
        .unwrap_err();
        assert_eq!(
            mutable_capture.code,
            "frontend.python.heap.module-binding-reassigned"
        );
    }

