    fn primitive_heap_function_calls_compose_transitively() {
        let result = verify_heap_module(
            "from nagini_contracts.contracts import *\n\nclass Marker:\n    pass\n\ndef leaf(value: int) -> int:\n    Ensures(Result() == value + 1)\n    return value + 1\n\ndef middle(value: int) -> int:\n    Ensures(Result() == value + 2)\n    return leaf(value) + 1\n\ndef top(value: int) -> int:\n    Ensures(Result() == value + 3)\n    return middle(value) + 1\n\ndef run() -> None:\n    observed = top(39)\n    Assert(observed == 42)\n",
            "transitive_primitive_callable.py",
            &[],
        )
        .unwrap();
        assert!(result.passed, "{:#?}", result.obligations);
        assert!(result.methods.iter().any(|method| method == "leaf"));
        assert!(result.methods.iter().any(|method| method == "middle"));
        assert!(result.methods.iter().any(|method| method == "top"));
    }

