    #[test]
    fn verified_module_predicate_exports_typed_body_globals_and_stable_identity() {
        let (_, provider) = verify_and_export_source_heap_module(
            "from nagini_contracts.contracts import *\n\nLIMIT = 1\n\nclass Cell:\n    value: int\n\n    def __init__(self) -> None:\n        Ensures(Acc(self.value))\n        Ensures(self.value == LIMIT)\n        self.value = LIMIT\n\n    @Predicate\n    def state(self) -> bool:\n        return Acc(self.value)\n\n@Predicate\ndef state(cell: Cell) -> bool:\n    return Acc(cell.value) and cell.value == LIMIT\n",
            "provider.py",
            "provider",
            &[],
        )
        .unwrap();
        assert_eq!(provider.predicate_names(), ["state"]);
        assert_eq!(provider.qualified_predicate_names(), ["provider.state"]);
        let module_identity = &provider.predicates["state"].identity;
        let class_identity = &provider.classes["Cell"].predicates["state"].identity;
        assert_eq!(module_identity, "module::provider::state");
        assert_ne!(module_identity, class_identity);

        let result = verify_heap_module_with_imports(
            "from nagini_contracts.contracts import *\nfrom provider import Cell, state\n\nLIMIT = 100\n\ndef run() -> None:\n    cell = Cell()\n    Fold(state(cell))\n    Unfold(state(cell))\n    Assert(cell.value == 1)\n",
            "consumer.py",
            &["run".to_owned()],
            &[provider],
        )
        .unwrap();
        assert!(result.passed, "{:#?}", result.obligations);
    }

