    #[test]
    fn heap_if_path_set_verifies_bilateral_and_mixed_early_returns() {
        for body in [
            "    if flag:\n        return 1\n    else:\n        return 2\n",
            "    if flag:\n        return 1\n    selected = 2\n    return selected\n",
        ] {
            let source = format!(
                "from nagini_contracts.contracts import *\n\nclass Marker:\n    value: int\n\ndef choose(flag: bool) -> int:\n    Ensures(Result() >= 1)\n    Ensures(Result() <= 2)\n{body}"
            );
            let result = verify_heap_module(&source, "heap_if_returns.py", &[]).unwrap();
            assert!(result.passed, "{result:#?}");
            let ids = result
                .obligations
                .iter()
                .map(|item| item.id.as_str())
                .collect::<BTreeSet<_>>();
            assert_eq!(ids.len(), result.obligations.len(), "{result:#?}");
            assert_eq!(
                result
                    .obligations
                    .iter()
                    .filter(|item| item.id.contains(":heap-function-complete:path:"))
                    .count(),
                2
            );
        }
    }

    #[test]
    fn heap_if_path_set_refutes_nonunit_fallthrough_and_supports_more_than_64_paths() {
        let fallthrough = verify_heap_module(
            "from nagini_contracts.contracts import *\n\nclass Marker:\n    value: int\n\ndef choose(flag: bool) -> int:\n    if flag:\n        return 1\n",
            "heap_if_fallthrough.py",
            &[],
        )
        .unwrap();
        assert!(!fallthrough.passed, "{fallthrough:#?}");
        assert!(fallthrough.obligations.iter().any(|item| {
            item.id
                .starts_with("choose:postcondition:implicit-return:path:")
                && item.status == ObligationStatus::Refuted
        }));

        let mut source = String::from(
            "from nagini_contracts.contracts import *\n\nclass Marker:\n    value: int\n\ndef choose(first: bool, stop: bool, a: bool, b: bool, c: bool, d: bool, e: bool, f: bool) -> int:\n    if first:\n        if stop:\n            return 0\n",
        );
        for name in ["a", "b", "c", "d", "e", "f"] {
            source.push_str(&format!(
                "    if {name}:\n        selected_{name} = 1\n    else:\n        selected_{name} = 2\n"
            ));
        }
        source.push_str("    return 1\n");
        let expanded = verify_heap_module(&source, "heap_if_many_paths.py", &[]).unwrap();
        assert!(expanded.passed, "{expanded:#?}");
    }

