    #[test]
    fn reference_field_writes_enforce_nominal_optional_and_receiver_types() {
        for (source, code) in [
            (
                "from nagini_contracts.contracts import *\n\nclass Left:\n    pass\nclass Right:\n    pass\nclass Holder:\n    item: Left\n    def __init__(self, item: Left) -> None:\n        Ensures(Acc(self.item))\n        self.item = item\ndef run(holder: Holder, wrong: Right) -> None:\n    Requires(Acc(holder.item))\n    holder.item = wrong\n",
                "frontend.python.heap.field-write-type-mismatch",
            ),
            (
                "from nagini_contracts.contracts import *\n\nclass Left:\n    pass\nclass Holder:\n    item: Left\n    def __init__(self, item: Left) -> None:\n        Ensures(Acc(self.item))\n        self.item = item\ndef run(holder: Holder) -> None:\n    Requires(Acc(holder.item))\n    holder.item = None\n",
                "frontend.python.heap.field-write-type-mismatch",
            ),
            (
                "from nagini_contracts.contracts import *\n\nclass Left:\n    pass\nclass Holder:\n    item: Left\n    def __init__(self, item: Left) -> None:\n        Ensures(Acc(self.item))\n        self.item = item\ndef run(holder: Holder, flag: bool) -> None:\n    Requires(Acc(holder.item))\n    selected = holder if flag else None\n    selected.item = holder.item\n",
                "frontend.python.heap.field-write-receiver-optional",
            ),
        ] {
            let error = verify_heap_module(source, "typed_field_write.py", &[]).unwrap_err();
            assert_eq!(error.code, code);
        }
    }

