    #[test]
    fn refuted_path_write_absorbs_only_that_path_and_skips_later_effects() {
        let result = verify_heap_module(
            "from nagini_contracts.contracts import *\n\nclass Pair:\n    left: int\n    right: int\n\ndef run(pair: Pair, flag: bool) -> None:\n    Requires(Acc(pair.right))\n    Ensures(Acc(pair.right))\n    if flag:\n        pair.left = 1\n        pair.right = 9\n    else:\n        pair.right = 2\n",
            "halted_write_path.py",
            &[],
        )
        .unwrap();
        assert!(!result.passed, "{result:#?}");
        let writes = result
            .obligations
            .iter()
            .filter(|item| item.id.starts_with("run:field-write-permission:"))
            .collect::<Vec<_>>();
        assert_eq!(writes.len(), 2, "{result:#?}");
        assert!(writes.iter().any(|item| {
            item.id.contains("field-write-permission:left")
                && item.status == ObligationStatus::Refuted
        }));
        assert!(
            writes.iter().any(|item| {
                item.id.contains("field-write-permission:right") && item.satisfied()
            })
        );
        assert_eq!(
            result
                .obligations
                .iter()
                .filter(|item| item.id.starts_with("run:postcondition:"))
                .count(),
            1,
            "{result:#?}"
        );
        assert_eq!(
            result
                .obligations
                .iter()
                .filter(|item| item.id.starts_with("run:heap-function-complete:path:"))
                .count(),
            1,
            "{result:#?}"
        );
    }

