    #[test]
    fn opaque_object_parameters_require_narrowing_before_typed_heap_use() {
        for (body, expected_code) in [
            (
                "    Assert(value == 1)\n",
                "frontend.python.heap.assert-reference-equality-left-unsupported",
            ),
            (
                "    if value:\n        pass\n",
                "frontend.python.heap.conditional-statement-condition-type-mismatch",
            ),
            (
                "    observed = value.marker\n",
                "frontend.python.heap.function-field-receiver-untyped",
            ),
            (
                "    Assert(value.marker == 1)\n",
                "frontend.python.heap.function-field-receiver-untyped",
            ),
            (
                "    Assert((value.marker == 1) and True)\n",
                "frontend.python.heap.function-field-receiver-untyped",
            ),
            (
                "    observed = 1 if value.marker else 0\n",
                "frontend.python.heap.function-field-receiver-untyped",
            ),
            (
                "    value.touch()\n",
                "frontend.python.heap.terminal-reference-call-receiver-unsupported",
            ),
            (
                "    holder = Holder(value)\n",
                "frontend.python.heap.constructor-call-nominal-argument-mismatch",
            ),
        ] {
            let source = format!(
                "from nagini_contracts.contracts import *\n\nclass Item:\n    marker: int\n    def touch(self) -> None:\n        pass\nclass Holder:\n    item: Item\n    def __init__(self, item: Item) -> None:\n        Ensures(Acc(self.item))\n        self.item = item\ndef run(value: object) -> None:\n{body}"
            );
            let error = verify_heap_module(&source, "opaque_object_misuse.py", &[]).unwrap_err();
            assert_eq!(error.code, expected_code, "{body}");
        }
    }

